L2_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L2_1.m_Talk_KOREA = "……오셨군요, 스승님."
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "……いらっしゃったんですね、師匠。"
L2_1.m_Talk_ENG = "So you're finally here, Master."
L2_1.m_Talk_TWN = "……師父來啦。"
L2_1.m_Talk_THA = "ในที่สุดคุณก็มานะครับ อาจารย์"
L2_1.m_Talk_VTN = "Vậy cuối cùng sư phụ đã tới."
L2_1.m_Talk_SCN = "……您来了啊，老师。"
L2_1.m_Talk_DEU = "Du bist also endlich da, Meisterin."
L2_1.m_Talk_FRA = "... Vous voilà enfin, Maître."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 295
L3_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_DESPAIR"
L3_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L3_1.m_Pos = "C"
L3_1.m_Talk_KOREA = "미안하군. 서두른다고 했는데…… 아무래도 늦어버린 것 같아."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "すまない。急いだつもりだったが……どうやら間に合わなかったようだ。"
L3_1.m_Talk_ENG = "Sorry. I tried to hurry… but I fear it's too late."
L3_1.m_Talk_TWN = "抱歉，說會趕到……結果還是晚了一步。"
L3_1.m_Talk_THA = "ขอโทษนะ ฉันรีบมาแล้ว... แต่ก็น่ากลัวจะสายไป"
L3_1.m_Talk_VTN = "Xin lỗi. Ta đã cố gắng nhanh nhất có thể... nhưng ta sợ rằng đã quá muộn."
L3_1.m_Talk_SCN = "对不起。本想快点的……结果好像还是来晚了。"
L3_1.m_Talk_DEU = "Es tut mir leid. Ich habe versucht, mich zu beeilen ... aber ich fürchte, es ist zu spät."
L3_1.m_Talk_FRA = "Désolée. J'ai fais au plus vite, mais j'ai bien peur qu'il soit trop tard..."
