L5_1 = {}
L5_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 295
L5_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L5_1.m_Talk_KOREA = "괜찮습니다. 스승님 탓이 아니에요."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "大丈夫です、師匠のせいではありません。"
L5_1.m_Talk_ENG = "It's okay. It's not your fault."
L5_1.m_Talk_TWN = "沒關係，不是師父的錯。"
L5_1.m_Talk_THA = "ไม่เป็นไรครับ ไม่ใช่ความผิดของคุณหรอก"
L5_1.m_Talk_VTN = "Không sao đâu. Đó không phải lỗi của sư phụ."
L5_1.m_Talk_SCN = "没关系，不是老师的错。"
L5_1.m_Talk_DEU = "Es ist okay. Es ist nicht deine Schuld."
L5_1.m_Talk_FRA = "Ne vous en faites pas. Ce n'est pas de votre faute..."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 295
L6_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L6_1.m_Talk_KOREA = "조금은 더 견딜 줄 알았는데…… 광증의 진행이 갑자기 빨라졌어요."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "もう少し耐えられると思いましたが……狂症の進行が急に早まりました。"
L6_1.m_Talk_ENG = "I thought I could hold out a bit longer… but the madness is accelerating."
L6_1.m_Talk_TWN = "我以為我還能再撐一下……但狂氣的作用突然加速。"
L6_1.m_Talk_THA = "ผมนึกว่าตัวเองจะทนได้อีกสักนิด... แต่ความคลุ้มคลั่งมันกำลังเพิ่มขึ้นใหญ่แล้วครับ"
L6_1.m_Talk_VTN = "Con tưởng con có thể cầm cự lâu hơn một chút… nhưng cơn điên đang bành trướng."
L6_1.m_Talk_SCN = "我本以为自己能再多坚持一会儿的……结果狂症突然严重了。"
L6_1.m_Talk_DEU = "Ich dachte, ich könnte noch ein bisschen länger durchhalten ... aber der Wahnsinn beschleunigt sich."
L6_1.m_Talk_FRA = "Je pensais pouvoir la réprimer encore un peu plus longtemps, mais... la folie gagne du terrain."
