L9_1 = {}
L9_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 295
L9_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L9_1.m_Talk_KOREA = "혹시…… 시윤이는 무사합니까?"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "あの……シリュウは無事ですか？"
L9_1.m_Talk_ENG = "Is… Shiyoon all right?"
L9_1.m_Talk_TWN = "我們時雲……他沒事吧？"
L9_1.m_Talk_THA = "ชิยุน... ปลอดภัยรึเปล่าครับ?"
L9_1.m_Talk_VTN = "… Shiyoon ổn chứ?"
L9_1.m_Talk_SCN = "那个……时云没事吧？"
L9_1.m_Talk_DEU = "Ist ... Shiyoon in Ordnung?"
L9_1.m_Talk_FRA = "Est-ce que... Charles est en sécurité ?"
L10_1 = {}
L10_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 295
L10_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L10_1.m_Talk_KOREA = "쓰러지기 전에 뒷모습을 본 것 같은데……. 확실하지가 않아요."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "倒れる前に後ろ姿を見たような気がしますが……確信できなくて。"
L10_1.m_Talk_ENG = "I thought I saw his back before I fell… But I'm not so sure."
L10_1.m_Talk_TWN = "我倒下前好像有看到他的背影……但又不太確定。"
L10_1.m_Talk_THA = "ผมว่าผมเห็นหลังเขาก่อนจะล้มไป... แต่ก็ไม่แน่ใจนัก"
L10_1.m_Talk_VTN = "Con nghĩ rằng con đã nhìn thấy bóng lưng nó trước khi ngã… Nhưng con không chắc lắm."
L10_1.m_Talk_SCN = "在倒下之前我好像看到他的背影了……不过不敢确定。"
L10_1.m_Talk_DEU = "Ich dachte, ich hätte seinen Rücken gesehen, bevor ich hingefallen bin ... Aber ich bin mir nicht so sicher."
L10_1.m_Talk_FRA = "Il me semble l'avoir aperçu juste avant de m'évanouir... mais je ne suis pas sûr."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 295
L11_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_IDLE"
L11_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Talk_KOREA = "……그 아이라면 창고에 잠시 눕혀 뒀다."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "……あの子なら倉庫に寝かせておいた。"
L11_1.m_Talk_ENG = "…The kid's lying in the warehouse."
L11_1.m_Talk_TWN = "……我先把他安置在倉庫裡。"
L11_1.m_Talk_THA = "... เด็กนั่นนอนอยู่ในโกดังน่ะ"
L11_1.m_Talk_VTN = "… Đứa trẻ đang nằm trong nhà kho."
L11_1.m_Talk_SCN = "……那孩子我暂时安置在仓库里了。"
L11_1.m_Talk_DEU = "... Der Junge liegt im Lager."
L11_1.m_Talk_FRA = "... Je l'ai allongé un instant dans l'entrepôt."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 295
L12_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "피를 많이 흘리긴 했지만, 목숨은 건졌어."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "かなり出血していたようだが、一命をとりとめた。"
L12_1.m_Talk_ENG = "He lost a lot of blood, but he'll make it."
L12_1.m_Talk_TWN = "雖然流了不少血，但撿回了一條小命。"
L12_1.m_Talk_THA = "เขาเสียเลือดมาก แต่จะรอด"
L12_1.m_Talk_VTN = "Nó mất rất nhiều máu, nhưng nó sẽ vượt qua."
L12_1.m_Talk_SCN = "虽然流了很多血，不过命保住了。"
L12_1.m_Talk_DEU = "Er hat viel Blut verloren, aber er wird es schaffen."
L12_1.m_Talk_FRA = "Il a perdu beaucoup de sang, mais il survivra."
