L14_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L14_1.m_Talk_KOREA = "그렇군요…… 다행입니다."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "そうだったんですね……よかったです。"
L14_1.m_Talk_ENG = "I see… Thank goodness."
L14_1.m_Talk_TWN = "原來如此……那就好。"
L14_1.m_Talk_THA = "ครับ... ค่อยยังชั่ว"
L14_1.m_Talk_VTN = "Con hiểu rồi… Cảm ơn Chúa."
L14_1.m_Talk_SCN = "这样啊……真是太好了。"
L14_1.m_Talk_DEU = "Ich verstehe ... Gott sei Dank."
L14_1.m_Talk_FRA = "Je vois... Me voilà rassuré."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 295
L15_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_DESPAIR"
L15_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L15_1.m_Pos = "C"
L15_1.m_Talk_KOREA = "뭔가…… 남길 말은 없나?"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "なにか……言い残すことはないか？"
L15_1.m_Talk_ENG = "Any last words?"
L15_1.m_Talk_TWN = "你……有什麼要交代的嗎？"
L15_1.m_Talk_THA = "มีอะไรจะสั่งเสียมั้ย?"
L15_1.m_Talk_VTN = "Có muốn trăn trối gì không?"
L15_1.m_Talk_SCN = "你……没什么话想留给他吗？"
L15_1.m_Talk_DEU = "Irgendwelche letzten Worte?"
L15_1.m_Talk_FRA = "... Un dernier mot avant d'en finir ?"
