L17_1 = {}
L17_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 295
L17_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L17_1.m_Talk_KOREA = "연화는…… 그 고통을 견디면서도…… 최선을 다했습니다."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "レンカは……その苦痛に耐えながらも……最善を尽くしました。"
L17_1.m_Talk_ENG = "Yeonhwa tried her best… even as she withstood all that pain…"
L17_1.m_Talk_TWN = "蓮華她…已經盡力………忍受那個痛苦了。"
L17_1.m_Talk_THA = "ยอนฮวาทำดีที่สุดแล้วครับ... ขนาดว่าเธอต้องแบกรับความเจ็บปวดทั้งหมดนั่น..."
L17_1.m_Talk_VTN = "Yeonhwa đã cố gắng hết sức mình… ngay cả khi cô ấy chịu đựng tất cả nỗi đau đó…"
L17_1.m_Talk_SCN = "莲华她……已经尽全力……承受痛苦了。"
L17_1.m_Talk_DEU = "Yeonhwa hat ihr Bestes gegeben ... obwohl sie all diesen Schmerzen standgehalten hat ..."
L17_1.m_Talk_FRA = "Yeonhwa a fait ce qu'elle a pu... malgré la souffrance... qu'elle a enduré..."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 295
L18_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L18_1.m_Talk_KOREA = "하지만 운명이란…… 번뇌란 참으로 끊어내기 어렵군요."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "しかし運命とは……煩悩というのは本当に断ち切れないものですね。"
L18_1.m_Talk_ENG = "But our fate… Kleshas seem to be impossibly insurmountable."
L18_1.m_Talk_TWN = "只是……終究無法擺脫命運和煩惱。"
L18_1.m_Talk_THA = "แต่ชะตาของเธอ... กิเลสนั่นมันคงเกินจะแบกรับไหวจริงๆ"
L18_1.m_Talk_VTN = "Nhưng số phận của cô ấy… Kleshas dường như không thể vượt qua được."
L18_1.m_Talk_SCN = "可是命运……和烦恼，真的是很难斩断啊。"
L18_1.m_Talk_DEU = "Aber unser Schicksal ... die Kleshas scheinen unüberwindbar zu sein."
L18_1.m_Talk_FRA = "Mais notre destin... nos Kleshas, c'est une malédiction insurmontable."
