L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 295
L21_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L21_1.m_Talk_KOREA = "그러니…… 마지막만큼은 고통 없이……"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "だから……最期だけは苦しませずに……"
L21_1.m_Talk_ENG = "So please… When you put her down…"
L21_1.m_Talk_TWN = "我希望……她最後可以沒有痛苦地……"
L21_1.m_Talk_THA = "เพราะงั้น... ตอนที่คุณจัดการกับเธอ..."
L21_1.m_Talk_VTN = "Vì vậy, xin vui lòng ... Khi xuống tay với cô ấy..."
L21_1.m_Talk_SCN = "所以……最后请让她……"
L21_1.m_Talk_DEU = "Also bitte ... in ihren letzten Momenten ..."
L21_1.m_Talk_FRA = "S'il vous plaît... vous devez soulager son agonie..."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 295
L22_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L22_1.m_Talk_KOREA = "그녀를…… 연화를 보내 주십시오……"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "彼女を……レンカを眠らせてください……"
L22_1.m_Talk_ENG = "Please make it painless for Yeonhwa…"
L22_1.m_Talk_TWN = "離……開……"
L22_1.m_Talk_THA = "อย่าให้ยอนฮวาต้องเจ็บปวดเลยนะครับ..."
L22_1.m_Talk_VTN = "Xin hãy đừng làm Yeonhwa quá đau…"
L22_1.m_Talk_SCN = "让莲华……没有痛苦地离开吧……"
L22_1.m_Talk_DEU = "Bitte lass Yeonhwa schmerzlos dahingehen ..."
L22_1.m_Talk_FRA = "Mettez un terme... à ses souffrances..."
