L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 295
L27_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L27_1.m_Talk_KOREA = "약속해 주세요, 스승님. 그 아이를 보살펴 주겠다고."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "約束してください、師匠。あの子の面倒を見てくれると。"
L27_1.m_Talk_ENG = "Promise me, Master. Promise me that you'll take care of him."
L27_1.m_Talk_TWN = "師父，答應我你會好好照顧他，"
L27_1.m_Talk_THA = "สัญญานะคะอาจารย์ สัญญาว่าจะดูแลเขา"
L27_1.m_Talk_VTN = "Sự phụ, hãy hứa với con, hãy hứa với con rằng sư phụ sẽ chăm sóc nó."
L27_1.m_Talk_SCN = "答应我，老师。照顾好那个孩子。"
L27_1.m_Talk_DEU = "Versprich es mir, Meisterin. Versprich mir, dass du dich um ihn kümmerst."
L27_1.m_Talk_FRA = "Maître, promettez-le moi. Promettez-moi que vous vous occuperez de mon enfant."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "EP7_ACT4_INTERLUDE_01@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 295
L28_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L28_1.m_Talk_KOREA = "그 아이가 저처럼 되지 않게……. 진실에서 멀어지게 해 주겠다고요."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "あの子が私と同じ道を歩まないように……真実から遠ざけてあげてください。"
L28_1.m_Talk_ENG = "Don't let him become like me… Please keep him as far away from the truth as possible."
L28_1.m_Talk_TWN = "不要讓他變得像我一樣……永遠不要讓他知道真相。"
L28_1.m_Talk_THA = "อย่าปล่อยให้เขาเป็นแบบฉัน... อย่าให้เขาต้องได้รู้ความจริง"
L28_1.m_Talk_VTN = "Đừng để nó trở nên giống con… Hãy giữ nó càng xa sự thật càng tốt."
L28_1.m_Talk_SCN = "不要让那个孩子变成我这样……让他远离真相。"
L29_1 = "Lass ihn nicht so werden wie ich ... Bitte halte ihn so weit wie möglich von der Wahrheit fern."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ne le laissez pas devenir comme moi. S'il vous plaît, tenez-le éloigné de la vérité."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP7_ACT4_INTERLUDE_01@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 295
L29_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L30_1 = "……그래, 그 정도라면."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "……それぐらいならいいだろう。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "…I will, if that's all you ask."
L29_1.m_Talk_ENG = L30_1
L30_1 = "……好，如果是這樣…"
L29_1.m_Talk_TWN = L30_1
L30_1 = "... ถ้าต้องการแค่นั้นก็จะทำให้นะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "… Được thôi."
L29_1.m_Talk_VTN = L30_1
L30_1 = "……好，这种程度的话。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Nun gut, wenn das alles ist,"
L29_1.m_Talk_DEU = L30_1
L30_1 = "... Si c'est ce que tu veux."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP7_ACT4_INTERLUDE_01@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 295
L30_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L31_1 = "약속하지."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "約束する。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I promise."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我答應你。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฉันสัญญา"
L30_1.m_Talk_THA = L31_1
L31_1 = "Ta hứa."
L30_1.m_Talk_VTN = L31_1
L31_1 = "我答应你。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "dann verspreche ich es."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tu as ma parole."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP7_ACT4_INTERLUDE_01@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 295
L31_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L32_1 = "고마워요……."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "……ありがとうございます。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Thank you…"
L31_1.m_Talk_ENG = L32_1
L32_1 = "謝謝你……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ขอบคุณค่ะ..."
L31_1.m_Talk_THA = L32_1
L32_1 = "Cảm ơn sư phụ…"
L31_1.m_Talk_VTN = L32_1
L32_1 = "谢谢您……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Vielen Dank ..."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Merci..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP7_ACT4_INTERLUDE_01@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 295
L32_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L33_1 = "그럼 이제…… 저도 가야 할 시간이네요. 그이가 기다리고 있어요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "それでは……そろそろ私も逝かなければ。あの人が待っています。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Then… I suppose it's time for me to go now. He's waiting for me."
L32_1.m_Talk_ENG = L33_1
L33_1 = "那麼……我也該離開了，他在等我。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ถ้าอย่างนั้น... คงถึงเลาที่ฉันต้องไปแล้วเหมือนกันสินะคะ เขารอฉันอยู่"
L32_1.m_Talk_THA = L33_1
L33_1 = "Vậy thì… con cho là đã đến lúc phải đi rồi. Anh ấy đang đợi con."
L32_1.m_Talk_VTN = L33_1
L33_1 = "那现在……我也该走了。他还在等我呢。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Dann... nehme ich an, es ist Zeit für mich, zu gehen. Er wartet auf mich."
L32_1.m_Talk_DEU = L33_1
L33_1 = "À mon tour maintenant de partir... d'aller le rejoindre."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP7_ACT4_INTERLUDE_01@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 295
L33_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L34_1 = "남길 말…… 아니, 전할 말은 없나?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "残したい言葉……いや、伝えたい言葉はないか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Any last words… I mean, anything you want to say to the kid?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "你有遺言……不，你有什麼話想對他說嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "มีอะไรจะสั่งเสียมั้ย... คือ มีอะไรอยากบอกลูกมั้ย?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cô có trăn trối gì không… Cô muốn nói gì với đứa trẻ?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "你没有什么要留给……不，要告诉他的吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Irgendwelche letzten Worte ...? Ich meine, was willst du dem Jungen sagen?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Un dernier mot... message pour votre fils ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP7_ACT4_INTERLUDE_01@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 295
L34_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L35_1 = "아시잖아요, 스승님. 전 그 아이에게 유언을 남길 수 없어요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ご存知でしょう、師匠。私はあの子に遺言を遺すことはできません。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "You know how it is, Master. I can't leave any words for that child."
L34_1.m_Talk_ENG = L35_1
L35_1 = "師父你也知道，我不能對那孩子留下遺言。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "คุณก็รู้นี่คะอาจารย์ว่ามันเป็นยังไง ฉันกล้าฝากอะไรถึงลูกหรอกค่ะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Sư phụ biết nó như thế nào không?. Con không thể để lại bất kỳ lời nào cho đứa trẻ đó."
L34_1.m_Talk_VTN = L35_1
L35_1 = "您也知道的，老师。我不能给那孩子留下遗言。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Du weißt doch, wie es ist, Meisterin. Ich kann keine Worte für dieses Kind hinterlassen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Vous savez bien que je ne peux rien lui dire, Maître."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP7_ACT4_INTERLUDE_01@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 295
L35_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L36_1 = "이미 용혈의 광기에 사로잡힌 이상…… 또다시 이성을 잃겠죠."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "すでに龍血の狂気に囚われている以上……また理性を失ってしまうでしょう。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Now that the Dragon Blood's madness has taken me… I will lose myself yet again."
L35_1.m_Talk_ENG = L36_1
L36_1 = "龍血的狂氣已經滲入我的思想……我會再次失去理智的。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ในเมื่อตอนนี้ความคลุ้มคลั่งของเลือดมังกรครอบงำฉันแล้ว ฉันก็จะเสียสติไปอีกครั้ง"
L35_1.m_Talk_THA = L36_1
L36_1 = "Giờ thì cơn điên cuồng của dòng máu rồng đã chiếm lấy con… Con sẽ lại đánh mất chính mình."
L35_1.m_Talk_VTN = L36_1
L36_1 = "一旦为龙血的疯狂所困……肯定会再次失去理智。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Jetzt, wo mich der Wahnsinn des Drachenbluts erfasst hat, werde ich mich erneut verlieren ..."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Maintenant que la folie a commencé à me consumer... Mon âme est condamnée."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP7_ACT4_INTERLUDE_01@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 295
L36_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L37_1 = "저와 접촉하게 되면 시윤이도 광기의 발현이 시작될 거예요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "私と接触すると、シリュウも狂気の発現が始まります。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "If I get in touch with Shiyoon, it will trigger the child's madness too."
L36_1.m_Talk_ENG = L37_1
L37_1 = "和時雲接觸的話，他就會開始發現狂氣的存在。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ขืนไปพูดอะไรกับชิยุน มีหวังความคลุ้มคลั่งในตัวลูกจะถูกปลุกไปด้วย"
L36_1.m_Talk_THA = L37_1
L37_1 = "Nếu con ở gần với Shiyoon, nó cũng sẽ kích hoạt cơn điên của thằng bé."
L36_1.m_Talk_VTN = L37_1
L37_1 = "跟我接触的话，时云身上的诅咒也会开始显现的。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wenn ich Kontakt mit Shiyoon aufnehme, wird das auch seinen Wahnsinn auslösen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Si j'entre en contact avec Charles, alors je risque de la lui transmettre."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP7_ACT4_INTERLUDE_01@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
