L38_1 = {}
L39_1 = "EP7_ACT4_INTERLUDE_01@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 295
L38_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L39_1 = "그러니까…… 시윤이 대신 스승님이 들어 주세요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "だから……シリュウの代わりに師匠が聞いてください。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "So instead of Shiyoon… Please hear these words on his behalf, Master."
L38_1.m_Talk_ENG = L39_1
L39_1 = "所以……我想對時雲說的話，就只能說給師父聽。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เพาระอย่างนั้น แทนที่จะฝากอะไรถึงชิยุน... อาจารย์ช่วยฟังแทนทีนะคะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Vì vậy, thay cho Shiyoon ... Xin sư phụ hãy nghe những lời này thay cho nó."
L38_1.m_Talk_VTN = L39_1
L39_1 = "所以……我想对他说的话，就只说给老师听吧。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Anstelle von Shiyoon ... Bitte höre diese Worte in seinem Namen, Meisterin."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Alors s'il vous plaît... Écoutez mes mots à sa place."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP7_ACT4_INTERLUDE_01@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 295
L39_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L40_1 = "한없이 괴롭고, 한없이 고통스러운 삶이었지만……."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "限りなく辛く、そして苦しい人生だったけど……"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Although my life was full of suffering and agony…"
L39_1.m_Talk_ENG = L40_1
L40_1 = "雖然我這一生在無盡的痛苦和折磨中度過……"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ถึงชีวิตฉันจะมีแต่ความทุกข์ทรมานและความเจ็บปวด"
L39_1.m_Talk_THA = L40_1
L40_1 = "Dù cuộc đời con đầy đau khổ và bất hạnh…"
L39_1.m_Talk_VTN = L40_1
L40_1 = "在充满无限痛苦和无尽折磨的生活里……"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Obwohl mein Leben voller Leiden und Qualen war ..."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Mon existence entière... n'était que souffrance et agonie."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP7_ACT4_INTERLUDE_01@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 295
L40_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L41_1 = "네가 있어 줘서……. 내가 인간이었다는 사실을 잊지 않을 수 있었다고."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "シリュウ、あなたがいてくれて……私が人間であったという事実を忘れずにいられた、と。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "It was all thanks to you… that I could hold onto my humanity."
L40_1.m_Talk_ENG = L41_1
L41_1 = "但因為有你……讓我忘不掉我曾經身為人的事實。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "แต่ทั้งหมดก็เพราะอาจารย์นะคะ... ที่ทำให้ฉันคงความเป็นมนุษย์ไว้ได้"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tất cả là nhờ có con… mà mẹ có thể giữ được nhân tính của mình."
L40_1.m_Talk_VTN = L41_1
L41_1 = "因为有你……我才得以记得自己是个人的事实。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "War es alles dank dir ... dass ich an meiner Menschlichkeit festhalten konnte."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Mais si j'ai mis si longtemps à renoncer à mon humanité... C'est grâce à toi."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP7_ACT4_INTERLUDE_01@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 295
L41_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L42_1 = "정말 고마웠고…… 행복했다고."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "本当にありがとう……幸せだった、と。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Thank you my child… My joy…"
L41_1.m_Talk_ENG = L42_1
L42_1 = "謝謝你……因為你我很幸福。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เพราะลูกของฉัน... ความสุขของฉัน..."
L41_1.m_Talk_THA = L42_1
L42_1 = "Cảm ơn con… Niềm vui của mẹ…"
L41_1.m_Talk_VTN = L42_1
L42_1 = "真的谢谢你……我很幸福。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Danke, mein Kind ... Du warst meine Freude ..."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Merci, mon fils... ma joie..."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
