L44_1 = "EP7_ACT4_INTERLUDE_01@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 295
L43_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L44_1 = "네 마지막 말, 확실하게 들었다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "お前の最期の言葉、確かに受け取った。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I heard your last words, loud and clear."
L43_1.m_Talk_ENG = L44_1
L44_1 = "最後那一句，我聽得很清楚。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันได้ยินคำสั่งเสียเธอชัดเจนแล้ว"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ta đã nghe thấy những lời cuối cùng của cô, rất rõ ràng."
L43_1.m_Talk_VTN = L44_1
L44_1 = "你最后的遗言，我听清楚了。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich habe deine letzten Worte gehört, laut und deutlich."
L43_1.m_Talk_DEU = L44_1
L44_1 = "J'ai bien entendu tes derniers mots."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP7_ACT4_INTERLUDE_01@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 295
L44_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L45_1 = "그럼, 덤벼라. 연화."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "では、かかってこい、レンカ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Now, come at me. Yeonhwa."
L44_1.m_Talk_ENG = L45_1
L45_1 = "那就來吧，蓮華，"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ทีนี้ก็เข้ามาเถอะ ยอนฮวา"
L44_1.m_Talk_THA = L45_1
L45_1 = "Lại đây Yeonhwa."
L44_1.m_Talk_VTN = L45_1
L45_1 = "那就来吧，莲华。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Jetzt greif mich an, Yeonhwa."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Et maintenant c'est l'heure, Yeonhwa."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP7_ACT4_INTERLUDE_01@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 295
L45_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L46_1 = "아니, 번뇌에 사로잡힌 마룡이여."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "いや、煩悩に囚われた魔龍よ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Or rather… the Demon Dragon swept up in Kleshas."
L45_1.m_Talk_ENG = L46_1
L46_1 = "不，是陷入煩惱的魔龍！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "หรือก็คือ... มังกรปีศาจที่ถูกกิเลสครอบงำ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Hay đúng hơn là… con rồng quỷ đã chiếm lấy Kleshas."
L45_1.m_Talk_VTN = L46_1
L46_1 = "不对，是为烦恼所困的魔龙。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Oder besser gesagt ... Dämonendrache, der von den Kleshas gefangen ist."
L45_1.m_Talk_DEU = L46_1
L46_1 = "L'heure de te libérer de tes Kleshas, dragon démoniaque."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP7_ACT4_INTERLUDE_01@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 295
L46_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L47_1 = "한때는 네 스승이었던 자로서……"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "かつてお前の師匠だった者として……"
L46_1.m_Talk_JPN = L47_1
L47_1 = "As your former Master…"
L46_1.m_Talk_ENG = L47_1
L47_1 = "就由這個曾經身為師父的我……"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ในฐานะอดีตอาจารย์ของเธอ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Với tư cách là sư phụ của cô…"
L46_1.m_Talk_VTN = L47_1
L47_1 = "作为你曾经的老师……"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Als deine ehemalige Meisterin ..."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Moi, ton ancien Maître..."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP7_ACT4_INTERLUDE_01@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 295
L47_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L48_1 = "최선을 다해 고통 없이, 단숨에 끝내 주겠다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "最善を尽くし、苦痛なく一息で終わらせてやる。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I'll try my best to make it quick and painless."
L47_1.m_Talk_ENG = L48_1
L48_1 = "我會盡量讓你不感受到痛苦的。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันจะทำให้เร็วและเจ็บปวดน้อยที่สุด"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ta sẽ cố gắng hết sức để kết thúc nhanh chóng và không đau đớn."
L47_1.m_Talk_VTN = L48_1
L48_1 = "我会尽量让你没有痛苦地离开。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich werde mein Bestes tun, um es schnell und schmerzlos zu gestalten."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je promets d'abréger tes souffrances."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
