L5_1 = "EP7_ACT4_INTERLUDE_01@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 295
L4_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "USER_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "그 창고에서 눈을 맞으며…… 힐데 소대장과 부모님의 대화를 들었겠지."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "雪が舞うあの倉庫で…… ヒルデ小隊長とご両親の会話を聞いただろう。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "In that snowy warehouse… You must have heard Hilde speak with your parents."
L4_1.m_Talk_ENG = L5_1
L5_1 = "那個下雪天，希爾德和你父母親的對話……你在倉庫裡都聽見了吧？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ในโกดังที่หิมะตกหนักนั่น... คุณคงได้ยินฮิลเด้คุยกับพ่อแม่คุณ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Trong nhà kho đầy tuyết đó… Cậu hẳn đã nghe Hilde nói chuyện với bố mẹ cậu."
L4_1.m_Talk_VTN = L5_1
L5_1 = "你应该是在那个雪天的仓库里……听到了希尔德队长和你父母的谈话吧。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "In diesem verschneiten Lagerhaus ... musst du Hilde mit deinen Eltern sprechen gehört haben."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Au cœur du blizzard, allongé dans cet entrepôt... Tu as entendu la conversation qu'à eue Hilde avec tes parents."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP7_ACT4_INTERLUDE_01@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 295
L5_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "USER_ADMIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "자네는 귀가 아주 밝은 편이었으니까."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "君は耳がとても良い方だからな。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "You've got very good hearing, after all."
L5_1.m_Talk_ENG = L6_1
L6_1 = "因為你的耳朵很敏銳。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "หูดีจริงๆ นะคุณนี่"
L5_1.m_Talk_THA = L6_1
L6_1 = "Sau cùng thì cậu có thính giác rất tốt."
L5_1.m_Talk_VTN = L6_1
L6_1 = "因为你的耳朵很好使。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Immerhin hast du ein sehr gutes Gehör."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Tu as l'ouïe fine, tu l'as dit toi-même."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP7_ACT4_INTERLUDE_01@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 295
L6_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "누구죠, 당신은?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "あなたは、誰ですか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Who are you?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "請問你是誰？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "คุณเป็นใครครับ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Ai vậy?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "你是什么人？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Wer sind Sie?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Qui êtes-vous ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP7_ACT4_INTERLUDE_01@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 295
L7_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "목소리가 익숙한데…… 절 아시나요?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "聞き覚えのある声ですが……僕のことを知っているのですか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Your voice sounds familiar… Do you know me?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "聲音好耳熟……我們認識嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เสียงคุณคุ้นจัง... คุณรู้จักผมด้วยเหรอ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Giọng của anh nghe có vẻ quen thuộc… Anh có biết tôi không?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "我感觉你的声音很熟悉……你认识我吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ihre Stimme kommt mir bekannt vor ... Kennen Sie mich?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Votre voix m'est familière... Je vous connais ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP7_ACT4_INTERLUDE_01@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 295
L8_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "USER_ADMIN_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "오랜 시간을 살다 보니, 나에겐 많은 이름들이 있다네."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "長い時間を生きているせいか、私には多くの名前があってね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I've been around long enough to be known by many names."
L8_1.m_Talk_ENG = L9_1
L9_1 = "我目前已經累積很多名字欸？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ผมอยู่มานานจนมีหลายชื่อน่ะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi đã sống đủ lâu và được biết đến với nhiều cái tên."
L8_1.m_Talk_VTN = L9_1
L9_1 = "活得年头多了，我也有了很多名字呢。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich bin schon lange genug auf der Welt, um unter vielen Namen bekannt zu sein."
L8_1.m_Talk_DEU = L9_1
L9_1 = "J'ai vécu assez longtemps pour qu'on m'appelle par plusieurs noms."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP7_ACT4_INTERLUDE_01@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 295
L9_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "USER_ADMIN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "관리자, 사장, 그리고 때로는…… 현자라고 불리기도 했지."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "管理者、社長、時には……賢者と呼ばれていた時もあった。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Administrator, Boss, and at one point… the Sage."
L9_1.m_Talk_ENG = L10_1
L10_1 = "什麼管理者啦，老闆啦，有時候人家還會叫我…… 智者呢！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ผู้บริหารเอย บอสเอย พอถึงจุดหนึ่งก็... นักปราชญ์"
L9_1.m_Talk_THA = L10_1
L10_1 = "Quản trị viên, Ông chủ, và tại một thời điểm… Hiền Nhân."
L9_1.m_Talk_VTN = L10_1
L10_1 = "管理者，老板，有时候……也叫贤者。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Administrator, Boss und irgendwann ... der Weise."
L9_1.m_Talk_DEU = L10_1
L10_1 = "L'Administrateur, le Directeur, et parfois même... le Sage."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "EP7_ACT4_INTERLUDE_01@60#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 60
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 295
L10_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "……당신이?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あなたが……？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "…That was you?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "……你說你？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "... คือคุณเองเหรอครับ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "… Đó là anh sao?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "……你是？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "... Das waren Sie?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Qui... Vous ?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP7_ACT4_INTERLUDE_01@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 295
L11_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "그렇군요. 그 로봇 뒤에 누군가 계실 줄은 알았지만……"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "そうだったんですね。あのロボットの裏に誰かが存在することは知っていましたが……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I see. I had a feeling someone would be behind that robot…"
L11_1.m_Talk_ENG = L12_1
L12_1 = "原來如此，我是有猜想過那個機器人裡面應該有某個人……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "อย่างนี้นี่เอง ผมก็ตะหงิดๆ อยู่ว่าคงมีใครอยู่เบื้องหลังหุ่นยนต์นั่น..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi hiểu rồi. Tôi có cảm giác hẳn có ai đó sẽ đứng sau con robot ấy…"
L11_1.m_Talk_VTN = L12_1
L12_1 = "原来如此。我想过那个机器人背后应该还有人……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Aha. Ich hatte das Gefühl, dass jemand hinter diesem Roboter stecken würde ..."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je vois. Je me disais bien que ce robot cachait quelque chose..."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP7_ACT4_INTERLUDE_01@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 295
L12_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "직접 보니 납득이 되네요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "直接この目で見れば、納得がいきますね。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "But now that I've met you in person, it all makes sense."
L12_1.m_Talk_ENG = L13_1
L13_1 = "現在親眼見到後，我猜的應該沒錯！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "แต่พอตอนนี้เราเจอกันแล้ว ทุกอย่างก็สมเหตุสมผลครับ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nhưng bây giờ tôi đã gặp anh trực tiếp, tất cả đều có ý nghĩa."
L12_1.m_Talk_VTN = L13_1
L13_1 = "亲眼一看，果然明白了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Aber jetzt, wo ich Sie persönlich kennengelernt habe, ergibt alles Sinn."
L12_1.m_Talk_DEU = L13_1
L13_1 = "À vous rencontrer en personne, je comprends mieux."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP7_ACT4_INTERLUDE_01@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 295
L13_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "그래서 여긴 어디죠? 전 분명 죽었을 텐데요?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "それで、ここはどこですか？　僕は確かに死んだはずですが。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "So where am I? I thought I was dead."
L13_1.m_Talk_ENG = L14_1
L14_1 = "不過這裡是哪裡？我不是已經死了嗎？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "แล้วนี่ผมอยู่ไหนครับเนี่ย? ผมนึกว่าตัวเองตายไปแล้วซะอีก"
L13_1.m_Talk_THA = L14_1
L14_1 = "Vậy tôi đang ở đâu? Tôi tưởng rằng tôi đã chết."
L13_1.m_Talk_VTN = L14_1
L14_1 = "所以这里是什么地方？我明明已经死了？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Wo bin ich also? Ich dachte, ich wäre tot."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mais quel est cet endroit ? On ne vient pas de me tuer ?"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP7_ACT4_INTERLUDE_01@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 295
L14_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "USER_ADMIN_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "맞아. 여긴 삶과 죽음의 경계 같은 곳이지."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "そうだ。ここは生と死の境界のような場所だ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "You're right. This is sort of like the boundary between life and death."
L14_1.m_Talk_ENG = L15_1
L15_1 = "沒錯，這裡彷彿就像是生與死的交界。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ก็ใช่ นี่ก็ประมาณพรมแดนระหว่างความเป็นกับความตายน่ะ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Cậu nói đúng. Đây giống như ranh giới giữa sự sống và cái chết."
L14_1.m_Talk_VTN = L15_1
L15_1 = "没错。这里是类似于生死交界的地方。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Du hast Recht. Das ist so etwas wie die Grenze zwischen Leben und Tod."
L14_1.m_Talk_DEU = L15_1
L15_1 = "C'est effectivement le cas. Nous sommes dans les limbes, à la frontière entre la vie et la mort."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP7_ACT4_INTERLUDE_01@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 295
L15_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "USER_ADMIN_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "용혈의 후계자들이 마지막으로 시험 받는 곳이기도 하고."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "龍血の後継者たちが最後の試練を受ける場所でもある。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "It's also where the heirs of Dragon Blood are given their final test."
L15_1.m_Talk_ENG = L16_1
L16_1 = "龍血的後裔會在這裡接受最後的考驗。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "และก็เป็นที่ที่ทายาทเลือดมังกรต้องรับมอบการทดสอบสุดท้ายด้วย"
L15_1.m_Talk_THA = L16_1
L16_1 = "Đó cũng là nơi những người thừa kế dòng máu rồng được làm bài kiểm tra cuối cùng."
L15_1.m_Talk_VTN = L16_1
L16_1 = "也是龙血继承者最后接受考验的地方。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Hier werden auch die Erben des Drachenbluts ihrer letzten Prüfung unterzogen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "C'est aussi ici que les héritiers du Sang de dragon doivent affronter leur ultime ordalie."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
