L18_1 = "EP7_ACT4_INTERLUDE_01@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 295
L17_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "USER_ADMIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "<color=#ffd34c>용</color>이 되기 위한 마지막 시험이지."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "<color=#ffd34c>龍</color>になるための、最後の試練だ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "The final test to become a <color=#ffd34c>Dragon</color>."
L17_1.m_Talk_ENG = L18_1
L18_1 = "就是成為<color=#ffd34c>龍</color>的最後一個考驗。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "การทดสอบสุดท้ายเพื่อกลายเป็น<color=#ffd34c>มังกร</color>"
L17_1.m_Talk_THA = L18_1
L18_1 = "Bài kiểm tra cuối cùng để trở thành <color=#ffd34c>rồng</color>."
L17_1.m_Talk_VTN = L18_1
L18_1 = "成为<color=#ffd34c>龙</color>的最后考验。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Der letzte Test, um ein <color=#ffd34c>Drache</color> zu werden."
L17_1.m_Talk_DEU = L18_1
L18_1 = "L'épreuve qui fera d'eux des <color=#ffd34c>Dragons</color>."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP7_ACT4_INTERLUDE_01@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 295
L18_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "USER_ADMIN_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "원래라면 자네는 이 곳에서 자네의 선조들이 쌓아 온 번뇌들과 마주했어야 하네."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "本来なら君はここで君の先祖たちが築いてきた煩悩と向き合うべきだった。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Normally, this is where you'd come to face the Kleshas your ancestors have accumulated."
L18_1.m_Talk_ENG = L19_1
L19_1 = "原本你應該在這裡面對你祖先們累積至今的煩惱。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ปกติแล้ว นี่เป็นที่ที่คุณต้องมาเพื่อเผชิญกับกิเลสที่บรรพบุรุษสั่งสมไว้"
L18_1.m_Talk_THA = L19_1
L19_1 = "Thông thường, đây là nơi cậu đến để đối mặt với Kleshas mà tổ tiên của cậu đã tích lũy."
L18_1.m_Talk_VTN = L19_1
L19_1 = "本来你应该在这里遇到你的先祖们积攒下来的烦恼。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Normalerweise würdest du hier auf die Kleshas treffen, die deine Vorfahren angesammelt haben."
L18_1.m_Talk_DEU = L19_1
L19_1 = "En temps normal, c'est ici que tu devrais faire face aux Kleshas qui t'ont été transmis par tes aïeux."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP7_ACT4_INTERLUDE_01@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 295
L19_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "USER_ADMIN_NULL_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "누대에 걸쳐 쌓여 왔던 망설임과 원한, 후회와 탐욕, 분노와 교만, 불신……."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "累代にわたり積み重なった逡巡と怨念、後悔と貪欲、怒りと傲慢、不信……"
L19_1.m_Talk_JPN = L20_1
L20_1 = "All the hesitations, grudges, regrets, greed, rage, arrogance, and incredulity built up over generations…"
L19_1.m_Talk_ENG = L20_1
L20_1 = "像是躊躇、怨恨、貪念、驕傲和懷疑……"
L19_1.m_Talk_TWN = L20_1
L20_1 = "มี่งความลังเล, ความอาฆาต, ความเสียใจ, ความเดือดดาล, ความหยิ่งผยอง และความสงสัยใคร่รู้ ที่สั่งสมกันมาทุกรุ่น..."
L19_1.m_Talk_THA = L20_1
L20_1 = "Tất cả những do dự, ác cảm, hối tiếc, tham lam, thịnh nộ, kiêu ngạo và hoài nghi được xây dựng qua nhiều thế hệ…"
L19_1.m_Talk_VTN = L20_1
L20_1 = "积攒了几代的犹豫和怨恨，后悔和贪婪，愤怒和傲慢，不信任……"
L19_1.m_Talk_SCN = L20_1
L20_1 = "All das Zögern, der Groll, das Bedauern, die Gier, die Wut, die Arroganz und die Ungläubigkeit, die sich über Generationen aufgebaut haben ..."
L19_1.m_Talk_DEU = L20_1
L20_1 = "La rancœur et la cupidité, les indécisions et les hésitations, l'arrogance et l'incrédulité. Tous ce ressentiment passé de génération en génération..."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP7_ACT4_INTERLUDE_01@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 295
L20_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "USER_ADMIN_NULL_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "그 모든 번뇌를 끊어낼 수 있다면 진정한 용으로 다시 태어나겠지만."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "そのすべての煩悩を断ち切ることができれば、真なる龍へと生まれ変わるだろう。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "If you can overcome all those Kleshas, you'll be reborn as a true Dragon."
L20_1.m_Talk_ENG = L21_1
L21_1 = "只要能斷開這些煩惱就能成為真正的龍。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ถ้าคุณเอาชนะกิเลสพวกนั้นได้ ก็จะได้เกิดใหม่เป็นมังกรตัวจริง"
L20_1.m_Talk_THA = L21_1
L21_1 = "Nếu cậu có thể vượt qua tất cả những Kleshas đó, cậu sẽ được tái sinh thành một con rồng thực thụ."
L20_1.m_Talk_VTN = L21_1
L21_1 = "如果能结束那所有烦恼，就能重生为真正的龙。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wenn du all diese Kleshas überwinden kannst, wirst du als wahrer Drache wiedergeboren."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Si tu arrives à le surmonter, autrement dire à vaincre tes Kleshas, alors tu devrais renaître. En un véritable Dragon..."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP7_ACT4_INTERLUDE_01@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 295
L21_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "USER_ADMIN_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "그러지 못한다면 자네 또한 자아를 잃은 채 용혈의 망령이 되어 또다른 번뇌를 쌓게 되겠지."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "それができなければ、\n君もまた自我を失った龍血の亡霊となり、\nさらに煩悩を一つ重ねることになるだろう。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Otherwise, you'll become another lost soul of Dragon Blood to add to the pile of Kleshas."
L21_1.m_Talk_ENG = L22_1
L22_1 = "失敗的話，你也會失去自我成為龍血的亡靈，再繼續累積其他煩惱。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ไม่อย่างนั้น คุณก็จะกลายเป็นวิญญาณเลือดมังกรหลงทางที่จะทับถมลงไปบนกองกิเลสพวกนั้น"
L21_1.m_Talk_THA = L22_1
L22_1 = "Nếu không, cậu sẽ trở thành một linh hồn máu rồng bị lạc lối khác thêm cho Kleshas."
L21_1.m_Talk_VTN = L22_1
L22_1 = "否则你也会失去自我，变成龙血中的亡灵，积攒其他新的烦恼。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Andernfalls wist du zu einer weiteren verlorenen Seele aus Drachenblut, die neue Kleshas beiträgt."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Et si tu échoues, ton âme se retrouverait à errer dans le flot perpétuel de Sang de dragon, venant s'ajouter aux Kleshas accumulés tout ce temps..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
