L25_1 = "USER_ADMIN_NULL_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "자네는 이곳에서 어떤 번뇌도 고통도 느끼고 있는 것 같지 않아."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "君はここで煩悩も苦痛も感じているようには見えないな。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "You don't seem to feel anything Kleshas or pain here."
L24_1.m_Talk_ENG = L25_1
L25_1 = "為什麼你好像沒有感受到任何煩惱或是痛苦？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "คุณดูเหมือนไม่รู้สึกถึงกิเลสหรือความเจ็บปวดอะไรที่นี่เลย"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cậu dường như không cảm thấy bất cứ Kleshas hoặc đau đớn gì ở đây."
L24_1.m_Talk_VTN = L25_1
L25_1 = "你在这里好像感觉不到任何烦恼和痛苦。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Du scheinst hier weder Kleshas noch Schmerzen zu spüren."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Tu n'as pas l'air tourmenté par tes Kleshas, ni rongé par la souffrance."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP7_ACT4_INTERLUDE_01@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 295
L25_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "USER_ADMIN_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "아니, 여기 오기 전에도 용혈의 광기에 침식되지 않았지."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "いや、ここ来る前から龍血と狂気に侵食されていなかった。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "In fact, you didn't even succumb to madness before you got here."
L25_1.m_Talk_ENG = L26_1
L26_1 = "而且在你來到這裡之前，不是已經受到龍血狂氣的侵蝕嗎？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เอาจริงๆ คือคุณไม่โดยความคลุ้มคลั่งกลืนกินก่อนจะมาที่นี่ด้วยซ้ำ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Trên thực tế, cậu thậm chí còn không chống chọi nổi cơn điên trước khi đến đây."
L25_1.m_Talk_VTN = L26_1
L26_1 = "不对，来这儿之前，你也没有被龙血的疯狂所侵蚀。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Tatsächlich bist du nicht einmal dem Wahnsinn verfallen, bevor du hierherkamst."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Pire, tu n'as même pas succombé la folie avant d'arriver ici."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP7_ACT4_INTERLUDE_01@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 295
L26_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "USER_ADMIN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "분명, 용혈의 정보 오염에 노출되어 있었으면서도 말이야."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "確か、龍血の情報汚染を受けていたにも関わらず。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Even when you were clearly exposed to the Dragon Blood that causes contamination of mind."
L26_1.m_Talk_ENG = L27_1
L27_1 = "你明明就有暴露在龍血的污染中。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "หรือแม้แต่ตอนที่คุณรู้ข้อมูลเรื่องการปนเปื้อนในเลือด"
L26_1.m_Talk_THA = L27_1
L27_1 = "Ngay cả khi cậu đã được tiếp xúc trực diện với thông tin về sự ô nhiễm của máu."
L26_1.m_Talk_VTN = L27_1
L27_1 = "你明明，也暴露在龙血的信息污染中。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Obwohl du eindeutig dem Drachenblut ausgesetzt warst, das den Geist verunreinigt."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Alors que tu avais pourtant été exposé au Sang de dragon, qui aurait dû contaminer ton esprit."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP7_ACT4_INTERLUDE_01@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 295
L27_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "USER_ADMIN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "어떻게 그게 가능했지?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "どうしてなんだ？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "How did you pull that off?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "為什麼你好像一副沒事的樣子？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "คุณยับยั้งมันได้ยังไง?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Sao cậu làm được thế."
L27_1.m_Talk_VTN = L28_1
L28_1 = "你是怎么做到的呢？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Wie hast du das hinbekommen?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Comment est-ce possible ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP7_ACT4_INTERLUDE_01@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 295
L28_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "USER_ADMIN_NULL_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "설마 그 구도자도 해내지 못했던, 번뇌를 극복하는 데 성공한 건가?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "まさかあの求道者も果たせなかった、煩悩の克服に成功したのか？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Did you manage to overcome Kleshas? That's a feat that even the Seeker could not accomplish."
L28_1.m_Talk_ENG = L29_1
L29_1 = "難道你克服了連求道者也勝不過的煩惱？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "คุณเอาชนะกิเลสได้งั้นเหรอ? นั่นขนาดผู้แสวงสัจจะยังทำไม่ได้เลยนะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Cậu đã vượt qua được Kleshas? Đó là một kỳ tích mà ngay cả Kẻ Tìm Kiếm cũng không thể thực hiện được."
L28_1.m_Talk_VTN = L29_1
L29_1 = "莫非你成功地做到了那个求道者也没能做到的事——战胜烦恼？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Konntest du Kleshas überwinden? Das ist eine Leistung, die selbst der Sucher der Wahrheit nicht vollbringen konnte."
L28_1.m_Talk_DEU = L29_1
L29_1 = "As-tu réussi à surmonter tes Kleshas ? Là où le Chercheur de vérité lui-même avait échoué ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP7_ACT4_INTERLUDE_01@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 295
L29_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "……모르겠군요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "……わかりません。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "…I’m not sure."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我不知道……"
L29_1.m_Talk_TWN = L30_1
L30_1 = "... ผมก็ไม่แน่ใจครับ"
L29_1.m_Talk_THA = L30_1
L30_1 = "…Tôi không chắc."
L29_1.m_Talk_VTN = L30_1
L30_1 = "……我不知道。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "... Ich bin mir nicht sicher."
L29_1.m_Talk_DEU = L30_1
L30_1 = "... Je ne sais pas."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP7_ACT4_INTERLUDE_01@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 295
L30_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "전 아직도 그 번뇌라든가 용이라든가 하는 것이 뭔지 이해하지 못하겠어요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "僕はまだ煩悩や龍が何なのか理解できません。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I still don't get what all this stuff about Kleshas or Dragons mean."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我連什麼煩惱，什麼龍的都還搞不清楚。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผมยังไม่เข้าเลยครับว่าไอ้เรื่องกิเลสเรื่องมังกรนี่มันคืออะไร"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi vẫn không hiểu tất cả những thứ này, Kleshas hay rồng, có ý nghĩa gì."
L30_1.m_Talk_VTN = L31_1
L31_1 = "我到现在都不明白那个烦恼还有龙究竟是什么。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich verstehe immer noch nicht, was all das Zeug über Kleshas oder Drachen bedeuten soll."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Ces histoires de Kleshas, de Dragons... Je crois que je ne saisis pas vraiment le sens de tout ça."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP7_ACT4_INTERLUDE_01@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 295
L31_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "전 그저…… 제 자신으로 살고 싶었을 뿐입니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "僕はただ……自分自身で生きたかっただけです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "All I wanted… was just to be me."
L31_1.m_Talk_ENG = L32_1
L32_1 = "我……只是想做我自己。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ผมก็แค่... อยากเป็นตัวของตัวเอง"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tất cả những gì tôi muốn ... chỉ là được là chính mình."
L31_1.m_Talk_VTN = L32_1
L32_1 = "我只是……想为我自己而活。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Alles was ich wollte ... war einfach, ich selbst zu sein."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Tout ce que je voulais... C'était être moi-même."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
