L34_1 = "EP7_ACT4_INTERLUDE_01@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 295
L33_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "그 성녀라는 분이 말하더군요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "あの聖女という方が言っていました。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "That so-called Saintess told me."
L33_1.m_Talk_ENG = L34_1
L34_1 = "那個叫聖女的有說過，"
L33_1.m_Talk_TWN = L34_1
L34_1 = "นักบุญหญิงคนนั้นบอกผม"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cô mà gọi là Thánh Nữ đã nói với tôi."
L33_1.m_Talk_VTN = L34_1
L34_1 = "那个叫圣女的人说。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Diese sogenannte Heilige hat es mir erzählt."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Cette prétendue prêtresse m'a dit quelque chose."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP7_ACT4_INTERLUDE_01@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 295
L34_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "삶은 복수라고, 살아간다는 것은 나 이외의 타인에게 복수하는 것이라고."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "人生は復讐で、生きていくということは僕以外の誰かに復讐をすることだと。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "She said life is vengeance, and that to go on living means to take vengeance on someone other than myself."
L34_1.m_Talk_ENG = L35_1
L35_1 = "報仇是要以其他人為對象而不是自己。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เธอว่าชีวิตคือการล้างแค้น และการมีชีวิตอยู่ต่อไปก็คือการล้างแค้นคนอื่น ไม่ใช่ตัวเราเอง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Cô ấy nói rằng cuộc sống là sự báo thù, và để tiếp tục sống có nghĩa là phải báo thù một người khác không phải bản thân mình."
L34_1.m_Talk_VTN = L35_1
L35_1 = "她说生活是复仇，活着就是向自己以外的别人复仇。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Sie sagte, das Leben sei eine Rache, und Weiterleben bedeute, sich an jemand anderem als mir selbst zu rächen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Que la vie était une vengeance, et que pour survivre, il fallait diriger sa vengeance sur quelqu'un d'autre."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP7_ACT4_INTERLUDE_01@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 295
L35_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "그래요. 그것도 삶을 살아가는 하나의 방법이겠죠."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "そうですね。それも一つの生き方でしょう。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I mean, sure. That's probably one way to live."
L35_1.m_Talk_ENG = L36_1
L36_1 = "沒錯，那麼做確實是報仇，"
L35_1.m_Talk_TWN = L36_1
L36_1 = "คือ แน่ละครับ นั่นก็วิถีหนึ่งในการดำรงชีวิต"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ý tôi là, chắc chắn. Đó có lẽ là một cách để sống."
L35_1.m_Talk_VTN = L36_1
L36_1 = "没错，那也是活下去的一个办法。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich meine, okay. Das ist wahrscheinlich eine Art zu leben."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Oui, bien sûr... Je conçois qu'on puisse vivre comme ça."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP7_ACT4_INTERLUDE_01@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 295
L36_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "하지만 그렇게 타인에게 투영된 자신의 모습만을 쫓다 보면……."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "しかし、そうやって他人に投影された自分の姿ばかり追いかけていては……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "But if you go on chasing after the projection of your image that other people see…"
L36_1.m_Talk_ENG = L37_1
L37_1 = "但若是焦點只放在怎麼向其他人報仇……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แต่ถ้าเราเอาแต่วิ่งไล่ตามเงาตัวเองที่คนอื่นเห็น..."
L36_1.m_Talk_THA = L37_1
L37_1 = "Nhưng nếu cứ đuổi theo hình ảnh của mình mà người khác nhìn thấy ở bản thân mình…"
L36_1.m_Talk_VTN = L37_1
L37_1 = "可是那样追逐他人眼里的自己的话……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Aber wenn man weiter der Projektion seines Bildes nachjagt, das andere Leute sehen ..."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Mais à force de courir après une image de soi projetée sur autrui..."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP7_ACT4_INTERLUDE_01@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 295
L37_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "사람은 어느 순간 전혀 다른 존재가 되어 버려요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "人はある瞬間に全く別の存在になってしまいます。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "You'll find yourself becoming someone else entirely one day."
L37_1.m_Talk_ENG = L38_1
L38_1 = "久而久之，自己就會在某個瞬間完全失去自我。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "วันหนึ่งเราคงรู้สึกว่าตัวเองกลายเป็นคนแปลกหน้าไปโดยสิ้นเชิงน่ะครับ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Một ngày nào đó, sẽ thấy mình hoàn toàn trở thành một người khác."
L37_1.m_Talk_VTN = L38_1
L38_1 = "人会在某个瞬间突然变成完全不同的存在。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wird man feststellen, dass man eines Tages zu jemand ganz anderem wird."
L37_1.m_Talk_DEU = L38_1
L38_1 = "On finit par devenir quelqu'un, quelque chose d'autre. Un être entièrement différent."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP7_ACT4_INTERLUDE_01@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 295
L38_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "전 그렇게 되고 싶지 않았어요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "僕はそうなりたくありません。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I don't want that for myself."
L38_1.m_Talk_ENG = L39_1
L39_1 = "而我，不想變成那樣。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ผมไม่อยากให้ตัวเองเป็นแบบนั้น"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi không muốn điều đó cho chính mình."
L38_1.m_Talk_VTN = L39_1
L39_1 = "我不想变成那样。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ich will das nicht für mich."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ce n'est pas ce que je voulais."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP7_ACT4_INTERLUDE_01@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 295
L39_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "USER_ADMIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "……그래서 미나 양을 쏘지 않은 건가?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "……だからミナ君を撃たなかったのか？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "…Is that why you didn't shoot Mina?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "……所以你沒有朝米娜開槍嗎？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "... แบบนี้รึเปล่านะคุณเลยไม่ยิงมีนา?"
L39_1.m_Talk_THA = L40_1
L40_1 = "… Đó là lý do tại sao cậu không bắn Mina ư?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "……所以你才没向米娜开枪吗？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Hast du deshalb nicht auf Mina geschossen?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "... C'est pour ça que tu n'as pas tiré sur Mina ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP7_ACT4_INTERLUDE_01@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L40_1.m_CutScenProcessKey = 90
L40_1.m_CutScenID = 295
L40_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "USER_ADMIN_NULL_NULL"
L40_1.m_CharStrID = L41_1
L41_1 = "그로 인해 번뇌와, 고통과, 후회를 얻고……. 심지어 목숨까지 잃게 된다고 하더라도?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "それによって煩悩や苦痛、後悔を得て……さらに命まで失うとしても？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Even if that would bring you all that Kleshas, suffering, and regret… And even cost you your life?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "因為這樣而得到煩惱、痛苦、後悔……甚至失去性命也無所謂嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ต่อให้ไม่ทำแล้วต้องเจอทั้งกิเลส, ความทุกข์ทรมาน และความเสียใจ... หรือกระทั่งแลกด้วยชีวิตก็เถอะ?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Ngay cả khi điều đó sẽ mang lại cho cậu tất cả những Kleshas đó, đau khổ và hối tiếc… Và thậm chí có khi cậu phải trả giá bằng mạng sống của mình?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "哪怕会因此陷入烦恼、痛苦和后悔……甚至会失去自己的生命？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Auch wenn dir das all diese Kleshas, Leiden und Bedauern bringen würde ... Und dich sogar dein Leben kosten würde?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Tout en sachant que cela t'apporterait les Kleshas, la souffrance, les regrets... et même la mort ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP7_ACT4_INTERLUDE_01@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 295
L41_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "……예전에 미나 양에게 했던 말이 있죠."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "……以前ミナさんに言ったんです。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "…I once told Mina something."
L41_1.m_Talk_ENG = L42_1
L42_1 = "……米娜之前說過，"
L41_1.m_Talk_TWN = L42_1
L42_1 = "... ผมเคยบอกอะไรมีนาอยู่ครับ"
L41_1.m_Talk_THA = L42_1
L42_1 = "… Tôi đã từng nói với Mina vài điều."
L41_1.m_Talk_VTN = L42_1
L42_1 = "……我以前跟米娜说过。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich habe Mina einmal etwas erzählt."
L41_1.m_Talk_DEU = L42_1
L42_1 = "... Un jour, j'ai dit quelque chose à Mina."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP7_ACT4_INTERLUDE_01@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 295
L42_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "자신을 잃어 버릴지도 모르는 결정과 마주했을 때는…… 결코 양보하지 말라고."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "自分を失ってしまうかもしれない決断と向き合った時は……決して譲るな、と。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I told her that she should never back down when she's met with a choice that could make her forfeit her true self."
L42_1.m_Talk_ENG = L43_1
L43_1 = "面對到可能會失去自我的決定時……她是絕對不會退讓的。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ผมบอกเธอว่า ถ้าไปเจอการตัดสินใจที่อาจทำให้ต้องละทิ้งตัวตนไปก็อย่ายอมครับ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi đã nói với cô ấy rằng đừng bao giờ lùi bước khi đứng trước sự lựa chọn có thể khiến cô ấy đánh mất con người thật của mình."
L42_1.m_Talk_VTN = L43_1
L43_1 = "面对可能会失去自己的决定时……绝对不能退让。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich habe ihr gesagt, dass sie niemals nachgeben sollte, wenn sie vor eine Entscheidung gestellt wird, die sie dazu bringen könnte, ihr wahres Selbst aufzugeben."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Je lui ai dit de ne jamais céder à un choix qui lui feraient renoncer... à qui elle est vraiment."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP7_ACT4_INTERLUDE_01@93#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 93
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 295
L43_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "제가 겪은 비극도, 고통도, 후회도 모두 제 일부입니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "僕が経験した悲劇も、苦痛も、後悔も、すべて僕の一部です。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "All the tragedy, suffering, and regret I've experienced are a part of me as well."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我所經歷到的悲劇、痛苦、後悔，都是我生命的一部分。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "โศกนาฏกรรม ความทุกข์ทรมาน ความเศร้าเสียใจอะไรทั้งหมดที่ผมเจอมาก็เป็นส่วนหนึ่งในตัวผมเองเหมือนกัน"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tất cả những bi kịch, đau khổ và hối tiếc mà tôi đã trải qua đều là một phần của tôi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我所经历的悲剧，痛苦，还有后悔，全都是我的一部分。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "All die Tragödien, Leiden und Reue, die ich erlebt habe, sind auch ein Teil von mir."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Les tragédies, les souffrances et les regrets que j'ai vécus... Tout cela fait partie de moi."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP7_ACT4_INTERLUDE_01@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 295
L44_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "그로 인해 저는 부모님이 절 사랑한다는 걸 알 수 있었고……"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "その結果、僕は両親に愛されていたことを知れましたし……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Because of that, I knew how much my parents loved me…"
L44_1.m_Talk_ENG = L45_1
L45_1 = "因為這樣，我可以知道我的父母親是愛我的……"
L44_1.m_Talk_TWN = L45_1
L45_1 = "และเพราะแบบนั้น ผมเลยรู้ดีครับว่าพ่อแม่รักผมขนาดไหน"
L44_1.m_Talk_THA = L45_1
L45_1 = "Vì thế, tôi biết bố mẹ tôi yêu tôi đến nhường nào…"
L44_1.m_Talk_VTN = L45_1
L45_1 = "因为这些，我才能知道父母是爱我的……"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Deswegen konnte ich verstehen, wie sehr meine Eltern mich liebten ..."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ce sont aussi ces épreuves qui m'ont fait comprendre à quel point mes parents m'aimaient."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP7_ACT4_INTERLUDE_01@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 295
L45_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "누구보다 강하지만 살아가는 것은 서툴기만 한 스승님을 만나게 되었고……"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "誰よりも強いけれど、生きることがとても下手な師匠に出会えて……"
L45_1.m_Talk_JPN = L46_1
L46_1 = "And I met my Master, who is stronger than anyone, but clumsy at life…"
L45_1.m_Talk_ENG = L46_1
L46_1 = "因為這樣，我才可以遇到能力很好實際上卻是個生活白癡的師父……"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แล้วผมก็ได้เจออาจารย์ ที่แข็งแกร่งกว่าใคร แต่เรื่องใช้ชีวิตคือเด๋อ..."
L45_1.m_Talk_THA = L46_1
L46_1 = "Và tôi đã gặp Sếp của mình, người mạnh hơn bất cứ ai, nhưng lại vụng về trong cuộc sống…"
L45_1.m_Talk_VTN = L46_1
L46_1 = "遇到了比任何人都强大，却不太会生活的老师……"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Und ich traf meine Meisterin, die stärker ist als jeder andere, aber ungeschickt im Leben ..."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Et puis c'est comme ça que j'ai rencontré le Maître, aussi invincible au combat qu'elle est perdue dans la vie..."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP7_ACT4_INTERLUDE_01@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 295
L46_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "미나 양이 세상을 구하는 모습도 볼 수 있었어요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ミナさんがこの世界を救う姿も見れました。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "And I even got to watch Mina save the world."
L46_1.m_Talk_ENG = L47_1
L47_1 = "因為這樣，我才能看到米娜拯救世界的英姿。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "แถมผมยังถึงขั้นได้เห็นมีนาช่วยโลกเอาไว้"
L46_1.m_Talk_THA = L47_1
L47_1 = "Và tôi thậm chí được xem Mina cứu thế giới nữa."
L46_1.m_Talk_VTN = L47_1
L47_1 = "还看到了米娜拯救世界的样子。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Und ich durfte sogar zusehen, wie Mina die Welt rettete."
L46_1.m_Talk_DEU = L47_1
L47_1 = "J'ai même eu l'occasion de voir Mina sauver le monde !"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP7_ACT4_INTERLUDE_01@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 295
L47_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "그래요. 누군가는 그걸 번뇌라고 부를 수도 있겠죠."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "そうですね。誰かはそれを煩悩と呼ぶこともあるでしょう。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Sure. Some might call that Kleshas or suffering."
L47_1.m_Talk_ENG = L48_1
L48_1 = "沒錯，有些人可能會將這些視為煩惱，"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ครับ บางคนคงเรียกมันว่ากิเลสหรือความทุกข์ทรมาน"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chắc chắn. Một số người có thể gọi đó là Kleshas hoặc đau khổ."
L47_1.m_Talk_VTN = L48_1
L48_1 = "是啊，也许有的人会称那些为烦恼。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Sicher. Manche nennen das vielleicht Kleshas oder Leiden."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Alors oui, certes. Les Kleshas, la souffrance, ou quel que soit le nom de cette chose..."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP7_ACT4_INTERLUDE_01@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 295
L48_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "하지만 설령 영원히 용이 되는 길을 포기하고 뱀으로 땅을 기게 되더라도……."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "しかし、たとえ永遠に龍になる道を諦めて、蛇となり地面を這うことになっても……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "But even if I must forfeit becoming a Dragon and remain as a snake that crawls the earth on its belly…"
L48_1.m_Talk_ENG = L49_1
L49_1 = "但就算無法成為一尾活龍，只能在地上做一條魯蛇……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แต่ต่อให้ต้องอดเป็นมังกรแล้วไปคลานเป็นหนอนอยู่บนพื้น..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Nhưng nếu tôi phải từ bỏ việc trở thành một con rồng và nằm xuống như một con sâu..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "可是就算永远放弃成为龙的那条路，变成蛇在地上爬行……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Aber selbst, wenn ich aufgeben muss, ein Drache zu werden und eine Schlange zu bleiben, die auf ihrem Bauch über die Erde kriecht ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Je n'y renoncerai pas."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP7_ACT4_INTERLUDE_01@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 295
L49_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "저는 번뇌를 버리지 않겠어요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "僕は煩悩を捨てません。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I will not renounce my Kleshas."
L49_1.m_Talk_ENG = L50_1
L50_1 = "我也不會扔掉煩惱。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ผมก็จะไม่ทิ้งกิเลสของตัวเองไปหรอกครับ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi sẽ không từ bỏ Kleshas của mình."
L49_1.m_Talk_VTN = L50_1
L50_1 = "我也不会抛下烦恼。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Werde ich auf meine Kleshas nicht verzichten."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Même si cela signifie que je dois abandonner le rêve draconique, et ramper comme un serpent à la surface de la terre jusqu'à la fin de mes jours."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP7_ACT4_INTERLUDE_01@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 295
L50_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "그것이…… 제가 살아가는 방법이니까요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "それが……僕の生き方ですから。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Because… that is the way I choose to live."
L50_1.m_Talk_ENG = L51_1
L51_1 = "因為這就是……我的生存之道。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เพราะ... นั่นคือวิถีชีวิตที่ผมเลือกไงครับ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Bởi vì… đó là cách tôi chọn để sống."
L50_1.m_Talk_VTN = L51_1
L51_1 = "因为那是……我活下去的办法。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Denn ... das ist die Art, wie ich lebe."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Telle est la vie que j'ai choisie..."
L50_1.m_Talk_FRA = L51_1
