L4_1 = "EP7_ACT4_INTERLUDE_01@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 295
L3_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "USER_ADMIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "이 멍청이가! 대체 무슨 짓을 한 건가?!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "この馬鹿が！　いったい何をしたんだ！？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "You fool! What have you done?!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "你這個笨蛋！你到底做了什麼？！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "โง่เอ๊ย! นี่คุณทำอะไรลงไปเนี่ย?!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Đồ ngốc! Cậu đã làm gì?!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "你这个笨蛋！到底在做什么？！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Du Dummkopf! Was hast du getan?!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Imbécile ! Qu'est-ce que tu as fait ?"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP7_ACT4_INTERLUDE_01@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 295
L4_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "USER_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "용혈이라는 건 결국 변종 클리포트 인자에 불과해."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "龍血なんて、結局は変種のクリフォト・ファクターにすぎない。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Dragon Blood is nothing but a variant Qliphoth Factor."
L4_1.m_Talk_ENG = L5_1
L5_1 = "所謂的龍血不過就是變種卡巴拉因子！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เลือดมังกรมันก็คือคลิฟอธแฟกเตอร์แบบหนึ่ง"
L4_1.m_Talk_THA = L5_1
L5_1 = "Máu rồng chẳng qua chỉ là một biến thể của Nhân Tố Qliphoth."
L4_1.m_Talk_VTN = L5_1
L5_1 = "所谓龙血，归根结底也不过是变种神圣因子。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Drachenblut ist nichts anderes als eine Variante des Klippot-Faktors."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Le Sang de Dragon n'est qu'un variant de l'agent Qlipoth !"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP7_ACT4_INTERLUDE_01@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 295
L5_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "USER_ADMIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "그렇게 많은 양을 주입하면 클리포트 인자가 네 운명과 결합되고 말아!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "そんなに大量を注入すればクリフォト・ファクターが君の運命と結びついてしまう！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "If you inject that much, the Qliphoth Factor will bond with your fate!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "注入這麼大的量，卡巴拉因子會和你的命運連結在一起的！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ถ้าฉีดมากไป คลิฟอธแฟกเตอร์จะผูกติดไปกับชะตาของคุณนะ!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nếu cậu tiêm nhiều như vậy, Nhân Tố Qliphoth sẽ gắn liền với số phận của cậu!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "你一下子注射那么多，神圣因子会跟你的命运融合的！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wenn du so viel spritzt, verbindet sich der Klippot-Faktor mit deinem Schicksal!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Si tu t'en injectes autant, celui-ci se retrouvera lié à ton destin !"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP7_ACT4_INTERLUDE_01@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 295
L6_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "USER_ADMIN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "무슨 소린지 모르겠나? 더는 인간이 아니게 된다고!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "どうなるかわからないのか！？　もう人間ではなくなるんだぞ！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Don't you see what that means? You won't be human anymore!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "你懂我的意思嗎？意思就是你會變得人不像人！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เข้าใจมั้ยว่ามันคือยังไง? ก็คือคุณจะไม่ใช่มนุษย์อีกต่อไปไง!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cậu không hiểu điều đó có nghĩa là gì ư? Cậu sẽ không còn là con người nữa!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "你懂不懂我在说什么？你会变成非人类！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Siehst du nicht, was das bedeutet? Du wirst kein Mensch mehr sein!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Ne comprends-tu pas ? Tu vas perdre ton humanité à jamais !"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP7_ACT4_INTERLUDE_01@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 295
L7_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "USER_ADMIN_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "죽어서도 구원받지 못해! 영원히 고통 받는단 말이야!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "死んでも救われない！　永遠に苦しむ羽目になる！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You'll never find redemption, even in death! You'll suffer for all eternity!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "就算死也無法得到救贖！永遠受到痛苦的折磨！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "คุณจะไม่มีวันหลุดพ้น ต่อให้ความตายก็ช่วยไม่ได้ มีแต่จะต้องทุกข์ทรมานไปตลอดกาล!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cậu sẽ không bao giờ tìm thấy sự cứu chuộc, ngay cả trong cái chết! Cậu sẽ đau khổ suốt đời!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "至死也不能得到救赎！永远承受痛苦的煎熬！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Du wirst niemals Erlösung finden, nicht einmal im Tod! Du wirst bis in alle Ewigkeit leiden!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Même la mort ne t'apportera pas le salut ! Tu souffriras pour l'éternité !"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP7_ACT4_INTERLUDE_01@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 295
L8_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "SAVIOR_NPC_FAILED_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "……알고 있어요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "……わかっています。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "…I'm aware."
L8_1.m_Talk_ENG = L9_1
L9_1 = "我知道……"
L8_1.m_Talk_TWN = L9_1
