L10_1.m_Talk_VTN = L11_1
L11_1 = "什么意思……！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Mach dich nicht lächerlich!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Ne sois pas ridicule !"
