L12_1 = "EP7_ACT4_INTERLUDE_01@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 295
L11_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "SAVIOR_NPC_FAILED_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "당신이 거쳐 온 무수한 세계들과 달리……. 이 세계는 아직 준비되지 못했어요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "あなたが経てきた無数の世界と違い……この世界はまだ準備ができていませんでした。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Unlike the countless worlds you've journeyed through… This world isn't ready yet."
L11_1.m_Talk_ENG = L12_1
L12_1 = "這個世界和你之前經歷過的無數個世界不同……這個世界還沒準備好，"
L11_1.m_Talk_TWN = L12_1
L12_1 = "นี่มันไม่เหมือนโลกนับไม่ถ้วนที่คุณเคยเดินทางผ่านมาหรอกนะ... โลกนี้ยังไม่พร้อม"
L11_1.m_Talk_THA = L12_1
L12_1 = "Không giống như vô số thế giới mà cậu đã trải qua… Thế giới này vẫn chưa sẵn sàng."
L11_1.m_Talk_VTN = L12_1
L12_1 = "跟你经历过的无数世界不同……这个世界还没准备好。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Im Gegensatz zu den unzähligen Welten, durch die du gereist bist ... ist diese Welt noch nicht fertig."
L11_1.m_Talk_DEU = L12_1
L12_1 = "À la différence de tous les mondes que vous avez visités... Celui-ci n'est pas encore prêt."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP7_ACT4_INTERLUDE_01@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 295
L12_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "SAVIOR_NPC_FAILED_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "그래서 자신을 지킬 대적자조차도 제대로 만들어내지 못했죠."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "だから自分を守る敵対者さえも、まともに作り出すことができませんでした。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "It hasn't even procured a proper Antagonist to protect itself."
L12_1.m_Talk_ENG = L13_1
L13_1 = "所以連保護自己的敵對者也製造不出來。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "มันยังไม่เคยเจอปฏิปักษ์ที่คู่ควรให้ต้องปกป้องตัวเองด้วยซ้ำ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nó thậm chí còn chưa gặp phải một Kẻ Chống Đối thích hợp để tự bảo vệ mình."
L12_1.m_Talk_VTN = L13_1
L13_1 = "所以连能够守护自己的敌对者都没能创造好。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Es hat sich nicht einmal einen vernünftigen Antagonisten erschaffen, um sich selbst zu schützen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Il n'a même pas encore réussi à créer de véritable Antagoniste qui puisse le protéger."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
