L14_1.m_fWaitTime = 0
L15_1 = "SAVIOR_NPC_FAILED_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "이제 이 어린 세계는 끝을 마주보고 있습니다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "今やこの幼い世界は終末に向かっています。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "This nascent world is already on the verge of extinction."
L14_1.m_Talk_ENG = L15_1
L15_1 = "現在這個年輕的世界正面臨到盡頭。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "โลกนี้เพิ่งเกิดขึ้นใหม่แต่ก็อยู่ ณ ปากเหวแห่งการสิ้นสูญแล้ว"
L14_1.m_Talk_THA = L15_1
L15_1 = "Thế giới non trẻ này đã trên bờ vực diệt vong."
L14_1.m_Talk_VTN = L15_1
L15_1 = "如今这个年轻的世界即将走到尽头。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Diese entstehende Welt steht bereits kurz vor dem Untergang."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ce monde n'est même pas encore complètement né qu'il est déjà voué à s'éteindre."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
