L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 295
L15_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "SAVIOR_NPC_FAILED_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "전 누구도 지켜내지 못한 반쪽짜리 대적자일 뿐이지만……"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "私は誰も守れなかった生半可な敵対者にすぎませんが……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Although I'm just an incomplete Antagonist who has failed to protect anyone…"
L15_1.m_Talk_ENG = L16_1
L16_1 = "雖然我只是個半吊子的敵對者……"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ถึงผมจะเป็นปฏิปักษ์ผู้บกพร่องที่ปกป้องใครไม่ได้สักคน..."
L15_1.m_Talk_THA = L16_1
L16_1 = "Mặc dù tôi chỉ là một Kẻ Chống Đối không hoàn chỉnh, người đã không thể bảo vệ bất kỳ ai…"
L15_1.m_Talk_VTN = L16_1
L16_1 = "虽然我只是一个没能守护任何人的半吊子敌对者……"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Obwohl ich nur ein unvollständiger Antagonist bin, der es versäumt hat, irgendjemanden zu beschützen ..."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Je suis peut être un Antagoniste défectueux qui n'a su protéger personne..."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
