L17_1 = "但我不會放棄！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แต่ผมก็จะไม่ยอมแพ้หรอก"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi không chịu bỏ cuộc."
L16_1.m_Talk_VTN = L17_1
L17_1 = "就算这样我也不会放弃。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Weigere ich mich, aufzugeben."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Mais je ne baisserai pas les bras."
