L18_1 = "EP7_ACT4_INTERLUDE_01@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 295
L17_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "SAVIOR_NPC_FAILED_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "그게 제가 살아가는 방식이니까요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "それが私の生き方ですから。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Because… that is the way I choose to live."
L17_1.m_Talk_ENG = L18_1
L18_1 = "因為那是我的生存之道！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เพราะ... นั่นคือวิถีชีวิตที่ผมเลือกไงครับ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Bởi vì… đó là cách tôi chọn để sống."
L17_1.m_Talk_VTN = L18_1
L18_1 = "因为那是我活下去的方式。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Denn ... das ist die Art, wie ich lebe."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Telle est la vie que j'ai choisie."
