L20_1 = "EP7_ACT4_INTERLUDE_01@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 295
L19_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "SAVIOR_NPC_FAILED_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "제 운명과 결합된 이 피를…… 다른 세계들에 넘길 겁니다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "私の運命と結びついたこの血を……他の世界に託します。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I'm going to pass this blood that's bonded with my fate… onto the other worlds."
L19_1.m_Talk_ENG = L20_1
L20_1 = "我要把和我的命運連結在一起的血……轉到其他世界。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ผมจะส่งต่อเลือดที่ผูกอยู่กับชะตาตัวเองนี่... ไปยังโลกอื่นๆ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tôi sẽ truyền dòng máu gắn liền với số phận của mình… sang các thế giới khác."
L19_1.m_Talk_VTN = L20_1
L20_1 = "我会把融合了我命运的血……转移到其他世界。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ich werde dieses Blut, das mit meinem Schicksal verbunden ist, an die anderen Welten weitergeben."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Ce sang lié à mon destin... Je vais le léguer à d'autres mondes."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP7_ACT4_INTERLUDE_01@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 295
L20_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "SAVIOR_NPC_FAILED_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "언젠가……. 후예들 중 누군가가……. 이 저주를 극복하고 제 힘을 이어받도록……."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "いつか……末裔の誰かが……この呪いを乗り越えて私の力を受け継ぐように……"
L20_1.m_Talk_JPN = L21_1
L21_1 = "So one day… one of my descendants may… overcome this curse and inherit my powers…"
L20_1.m_Talk_ENG = L21_1
L21_1 = "總有一天……我的後裔中，會有一個人……克服這個詛咒獲得我的力量……"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เผื่อว่าวันหนึ่ง... ลูกหลานของผม... อาจจะเอาชนะคำสาปนี้แล้วสืบทอดพลังของผมไปได้..."
L20_1.m_Talk_THA = L21_1
L21_1 = "Vì vậy, một ngày nào đó… một trong những hậu duệ của tôi có thể… vượt qua lời nguyền này và kế thừa sức mạnh của tôi…"
L20_1.m_Talk_VTN = L21_1
L21_1 = "总有一天……我的后代中会有人……战胜这诅咒并继承我的力量……"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Eines Tages ... könnte einer meiner Nachkommen ... diesen Fluch überwinden und meine Kräfte erben ..."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Un jour, peut-être... Un de mes descendants parviendra à déjouer cette malédiction, et hériter de mes pouvoirs."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP7_ACT4_INTERLUDE_01@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 295
L21_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "SAVIOR_NPC_FAILED_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "그래서 그들의 세계에도 닥쳐 올, 종말을 막을 수 있게……"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そして、彼らの世界に迫る終末を食い止められるように……"
L21_1.m_Talk_JPN = L22_1
L22_1 = "So they may prevent the inevitable extinction of their own world…"
L21_1.m_Talk_ENG = L22_1
L22_1 = "如此一來，就可以阻止他們的世界會面臨到的末日……"
L21_1.m_Talk_TWN = L22_1
L22_1 = "พวกเขาจะได้ป้องกันไม่ให้โลกของตัวเองต้องเผชิญการดับสูญอันหลีกเลี่ยงไม่ได้"
L21_1.m_Talk_THA = L22_1
L22_1 = "Để họ có thể ngăn chặn sự tuyệt chủng không thể tránh khỏi của thế giới của riêng họ…"
L21_1.m_Talk_VTN = L22_1
L22_1 = "最终得以阻止他们的世界末日……"
L21_1.m_Talk_SCN = L22_1
L22_1 = "So könnte er das unvermeidliche Aussterben seiner eigenen Welt verhindern ..."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Il pourra alors empêcher l'extinction inéluctable de son monde..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP7_ACT4_INTERLUDE_01@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 295
L22_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "USER_ADMIN_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "자네의 후예들은? 자네 결정으로 괴로워할 그 사람들은?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "君の末裔たちは？　君の決定で苦しむあの人たちのことは？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "But what about your descendants? Will they not suffer because of your decision?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "你的後裔？你是說因為你的決定而受苦的人？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แต่ลูกหลานคุณจะเป็นยังไงล่ะ? พวกเขาจะไม่ต้องทุกข์ทรมานเพราะการตัดสินใจของคุณเหรอ?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Nhưng con cháu của cậu thì sao? Họ sẽ không phải chịu đau khổ vì quyết định của cậu chứ?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "你的后代？你在说那些因你的决定而承受痛苦的那些人吗？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Aber was ist mit deinen Nachkommen? Werden sie nicht unter deiner Entscheidung leiden?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Mais... Et tes descendants ? Et la vie de souffrance qui les attends ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP7_ACT4_INTERLUDE_01@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 295
L23_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "SAVIOR_NPC_FAILED_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "……누군가는 짊어져야 할 업보입니다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "……誰かが背負うべき因果です。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "…Someone's bound to carry on the legacy of this karma."
L23_1.m_Talk_ENG = L24_1
L24_1 = "……必須有人背起這個業障。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "... ต้องมีคนสืบทอดมรดกกรรมนี้ต่อไป"
L23_1.m_Talk_THA = L24_1
L24_1 = "… Ai đó nhất định phải mang theo di sản của nghiệp này."
L23_1.m_Talk_VTN = L24_1
L24_1 = "……总是要有人背负这个业障的。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Jemand muss das Vermächtnis dieses Karmas weiterführen."
L23_1.m_Talk_DEU = L24_1
L24_1 = "L'héritage de mon karma... doit être transmis."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP7_ACT4_INTERLUDE_01@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 295
L24_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "SAVIOR_NPC_FAILED_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "이걸로 하나의 세계라도, 단 하나의 세계라도……. 멸망의 굴레를 끊어낼 수 있다면……."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "これで一つの世界でも、たった一つの世界でも……滅亡のしがらみを断ち切ることができるのなら……"
L24_1.m_Talk_JPN = L25_1
L25_1 = "If this can prevent the cycle of extinction… for even one world…"
L24_1.m_Talk_ENG = L25_1
L25_1 = "只要這樣可以讓一個世界，就算只有一個世界也好……斷開滅亡的束縛……"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ถ้านี่จะป้องกันวัฏจักรแห่งการดับสูญได้... แม้เพียงแก่โลกใบเดียวก็ตาม..."
L24_1.m_Talk_THA = L25_1
L25_1 = "Nếu điều này có thể ngăn chặn chu kỳ tuyệt chủng… cho dù chỉ một thế giới…"
L24_1.m_Talk_VTN = L25_1
L25_1 = "哪怕只有一个世界，只有一个世界也好……能因此斩断灭亡的枷锁……"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Wenn dies den Kreislauf des Aussterbens verhindern kann ... für nur eine Welt ..."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Si c'est le prix pour enrayer le cycle de destruction perpétuelle, ne serait-ce que pour un monde... Je suis prêt à le payer."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP7_ACT4_INTERLUDE_01@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 295
L25_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "USER_ADMIN_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "그런 바보 같은……"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "そんなバカな……"
L25_1.m_Talk_JPN = L26_1
L26_1 = "How foolish…"
L25_1.m_Talk_ENG = L26_1
L26_1 = "真是愚蠢的行為……"
L25_1.m_Talk_TWN = L26_1
L26_1 = "โง่อะไรแบบนี้..."
L25_1.m_Talk_THA = L26_1
L26_1 = "Thật ngu ngốc…"
L25_1.m_Talk_VTN = L26_1
L26_1 = "你这个傻瓜……"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Wie dumm ..."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Imbécile..."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP7_ACT4_INTERLUDE_01@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 295
L26_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "USER_ADMIN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "그게 얼마나 걸릴지 생각해 본 적은 있나? 확률적으로 얼마나 희박한지는?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "それがどれほどかかるか、どれほど可能性が低いかは考えたのか？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Have you ever thought about how long that could take? How statistically impossible that will be?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "你知道這要花多久的時間嗎？你有算過這個機率有多低嗎？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ได้คิดบ้างมั้ยว่ามันจะยาวนานขนาดไหน? มันมีความเป็นไปไม่ได้ทางสถิติขนาดไหน?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Cậu đã bao giờ nghĩ điều đó có thể mất bao lâu chưa? Điều đó sẽ không thể tính toán được như thế nào?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "你有没有想过那要花多长时间？几率有多小？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Hast du schon einmal darüber nachgedacht, wie lange das dauern könnte? Wie statistisch unmöglich das sein wird?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "As-tu seulement pensé au temps que cela pourrait prendre ? Et que la réussite de ton plan est presque statistiquement impossible ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP7_ACT4_INTERLUDE_01@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 295
L27_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "SAVIOR_NPC_FAILED_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "하지만 언젠가는 도달할 겁니다. 전 믿고 있어요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "それでもいつかは到達するでしょう。私は信じています。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "But we'll get there one day. I have faith."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我相信總有一天會發生的，我堅決相信！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "วันนั้นจะมาถึงเข้าสักวันครับ ผมเชื่ออย่างนั้น"
L27_1.m_Talk_THA = L28_1
L28_1 = "Nhưng chúng ta sẽ thành công vào một ngày nào đó. Tôi có niềm tin."
L27_1.m_Talk_VTN = L28_1
L28_1 = "可是总有一天会到来的，我相信。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Aber wir werden es eines Tages schaffen. Ich habe Zuversicht."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Presque, mais pas complètement. Ça finira par marcher, j'en suis convaincu."
L27_1.m_Talk_FRA = L28_1
