L31_1 = "SAVIOR_NPC_FAILED_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "반드시, 그렇게 될 거라고."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "必ず、そうなると。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "It must come to that. No matter what."
L30_1.m_Talk_ENG = L31_1
L31_1 = "一定會發生的！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผมต้องทำให้ได้ ไม่ว่ายังไงก็ตาม"
L30_1.m_Talk_THA = L31_1
L31_1 = "Hẳn là thế. Cho dù có chuyện gì đi nữa."
L30_1.m_Talk_VTN = L31_1
L31_1 = "一定，会的。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Dazu wird es kommen. Egal wie."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Ça doit marcher. Coûte que coûte."
L30_1.m_Talk_FRA = L31_1
