L33_1 = "EP7_ACT4_INTERLUDE_01@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 295
L32_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "USER_ADMIN_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "……그렇군. 결국 도달했군."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "……そうか。ついに到達したのか。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I see... So we're finally here."
L32_1.m_Talk_ENG = L33_1
L33_1 = "……原來如此，就是現在嗎？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "อย่างนี่นี่เอง... ในที่สุดเราก็มาถึงแล้วสินะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi hiểu rồi ... Vậy là, cuối cùng chúng ta đã ở đây."
L32_1.m_Talk_VTN = L33_1
L33_1 = "……原来如此，就是现在吗？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich verstehe ... Also sind wir endlich da."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Je vois... Alors, nous y sommes."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP7_ACT4_INTERLUDE_01@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 295
L33_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "USER_ADMIN_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "번뇌를 잊을 필요도, 태우거나, 초월할 필요도 없다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "煩悩を忘れることも、焼却や超越する必要もない。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "There's no need to forget, scorch, or overcome Kleshas…"
L33_1.m_Talk_ENG = L34_1
L34_1 = "不需要忘記、挪去或是超越煩惱，"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เราไม่จำเป็นลืม แผดเผา หรือเอาชนะกิเลส..."
L33_1.m_Talk_THA = L34_1
L34_1 = "Không cần phải quên, thiêu đốt hay vượt qua Kleshas…"
L33_1.m_Talk_VTN = L34_1
L34_1 = "烦恼既不需要去遗忘，也不需要根除，更不需要去超越。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Es ist nicht nötig, Kleshas zu vergessen, zu versengen oder zu besiegen ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Pas besoin d'oublier, de détruire ou même de surmonter les Kleshas..."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP7_ACT4_INTERLUDE_01@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 295
L34_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "USER_ADMIN_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "삶이란……. 곧 번뇌이기 때문이다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "人生とは……すなわち煩悩だからだ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "For life itself… is Kleshas."
L34_1.m_Talk_ENG = L35_1
L35_1 = "因為人生……本來就是充滿煩惱。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เพราะชีวิตเอง... ก็คือกิเลสอยู่แล้ว"
L34_1.m_Talk_THA = L35_1
L35_1 = "Vì chính cuộc sống… là Kleshas."
L34_1.m_Talk_VTN = L35_1
L35_1 = "因为生活……本身就是烦恼。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Denn das Leben selbst... besteht aus Kleshas."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Car ces Kleshas sont le fondement même de nos existences."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP7_ACT4_INTERLUDE_01@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 295
L35_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "USER_ADMIN_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "삶을 살아간다는 것은, 번뇌이자 또한 축복이기에."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "生きていくということは煩悩であり、そして祝福でもある。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "To live means to suffer Kleshas, but it is also a blessing."
L35_1.m_Talk_ENG = L36_1
L36_1 = "人活著就是會有煩惱，也會有幸福。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "การมีชีวิตอยู่คือการต้องทุกข์ทนกับกิเลส แต่ก็เป็นของขวัญด้วย"
L35_1.m_Talk_THA = L36_1
L36_1 = "Sống có nghĩa là hứng chịu Kleshas, nhưng đó cũng là một điều may mắn."
L35_1.m_Talk_VTN = L36_1
L36_1 = "活着既是烦恼也是祝福。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Zu leben bedeutet, Kleshas zu erleiden, aber das ist auch ein Segen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Vivre, c'est souffrir. Mais quelque part, c'est une bénédiction."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP7_ACT4_INTERLUDE_01@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 295
L36_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "USER_ADMIN_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "……늘 그렇듯 말은 쉬워도 깨우치기는 쉽지 않지."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "……いつものように言葉で言うのは簡単だが、悟ることは簡単ではない。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "As always… it's easier said than done."
L36_1.m_Talk_ENG = L37_1
L37_1 = "……這麼簡單的道理，我們卻常常想不明白。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แต่ก็เป็นแบบนี้ตลอดสินะ... พูดง่ายทำยาก"
L36_1.m_Talk_THA = L37_1
L37_1 = "Như mọi khi… nói thì dễ hơn làm."
L36_1.m_Talk_VTN = L37_1
L37_1 = "……一如既往地，说起来容易，领悟起来却很难呢。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wie immer ... leichter gesagt als getan."
L36_1.m_Talk_DEU = L37_1
L37_1 = "... Bien sûr, c'est facile à dire. "
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP7_ACT4_INTERLUDE_01@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
