L39_1 = "EP7_ACT4_INTERLUDE_01@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 295
L38_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "USER_ADMIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "그 친구가 용혈을 가져간 것이 헛수고는 아니었군."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "あの友人の龍血を持っていったことは無駄ではなかった。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I suppose my old friend didn't take the Dragon Blood in vain after all."
L38_1.m_Talk_ENG = L39_1
L39_1 = "原來他不是白忙一場，"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ท่าว่าสุดท้ายที่เพื่อนเก่าผมฉีดเลือดมังกรไปจะไม่สูญเปล่าแล้ว"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi cho rằng rốt cuộc người bạn cũ của tôi đã không uống máu rồng một cách vô ích."
L38_1.m_Talk_VTN = L39_1
L39_1 = "看来让那个人拿走龙血并不是白费力气呢。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ich nehme an, mein alter Freund hat das Drachenblut doch nicht umsonst genommen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Au bout du compte, mon vieil ami n'aura pas pris le Sang de dragon pour rien."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP7_ACT4_INTERLUDE_01@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 295
L39_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "USER_ADMIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "나도 이제 조금은 짐을 내려놓을 수 있겠어."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "私もこれで少しは肩の荷が下りたよ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I can finally make peace with myself a little more."
L39_1.m_Talk_ENG = L40_1
L40_1 = "現在我終於也可以稍微卸下重擔了。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ในที่สุดผมก็สงใจได้มากขึ้นอีกนิดซะที"
L39_1.m_Talk_THA = L40_1
L40_1 = "Cuối cùng thì tôi cũng có thể an ủi bản thân nhiều hơn một chút."
L39_1.m_Talk_VTN = L40_1
L40_1 = "如今我肩上的担子也能稍微放下一些了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Endlich kann ich ein bisschen mehr Frieden mit mir schließen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Voilà qui fait un fardeau de moins à porter..."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
