L43_1 = "EP7_ACT4_INTERLUDE_01@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 295
L42_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "……전 이제 어떻게 되죠?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "……僕はどうなるんですか？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "…So what's going to happen to me now?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "……那我現在該怎麼辦？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "... แล้วตอนนี้จะเกิดอะไรขึ้นกับผมเหรอครับ?"
L42_1.m_Talk_THA = L43_1
L43_1 = "… Vậy điều gì sẽ xảy ra với tôi bây giờ?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "……我之后会怎么样？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Also, was wird jetzt mit mir passieren?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "... Qu'est-ce qui va m'arriver ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP7_ACT4_INTERLUDE_01@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 295
L43_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "죽는 건가요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "死ぬんですか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Am I going to die?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "去死嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ผมจะตายมั้ยครับ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi sắp chết ư?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "会死吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Werde ich sterben?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je vais mourir ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP7_ACT4_INTERLUDE_01@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 295
L44_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "USER_ADMIN_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "왜? 죽고 싶은가?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "それを聞く理由は？　死にたいのか？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Why? Do you wish to die?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "為什麼？你想死嗎？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ทำไมล่ะ? คุณอยากตายเหรอ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tại sao? Cậu có muốn chết không?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "怎么？你想死？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Wieso denn? Willst du sterben?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Pourquoi ? C'est ce que tu veux ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP7_ACT4_INTERLUDE_01@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 295
L45_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "그런 건 아니지만…… 조금은 미련이 남네요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "そういうわけではありませんが……少し未練が残ってますね。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Not really… I mean, there's one last thing I'd like to do."
L45_1.m_Talk_ENG = L46_1
L46_1 = "當然不想……我還有想完成的事。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ก็ไม่เชิงครับ... คือ มันยังเหลืออะไรที่ผมอยากทำอยู่เรื่องหนึ่ง"
L45_1.m_Talk_THA = L46_1
L46_1 = "Không thực sự… Ý tôi là, có một điều cuối cùng tôi muốn làm."
L45_1.m_Talk_VTN = L46_1
L46_1 = "那倒不是……我还有些遗憾。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Nicht wirklich ... ich meine, da ist noch eine letzte Sache, die ich gerne machen würde."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Pas vraiment... Il me reste encore une chose à faire."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP7_ACT4_INTERLUDE_01@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 295
L46_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "고맙다는 말을 하고 싶어요. 스승님에게."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "感謝の言葉を伝えたいです、師匠に。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I want to go say thank you. To my Master."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我想和師父說聲謝謝。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ผมอยากขอบคุณอาจารย์น่ะครับ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tôi muốn đi nói lời cảm ơn. Gửi đến Sếp của tôi."
L46_1.m_Talk_VTN = L47_1
L47_1 = "我想向老师说声谢谢。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich möchte Danke sagen. Zu meiner Meisterin."
L46_1.m_Talk_DEU = L47_1
L47_1 = "J'aimerais... remercier le Maître."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP7_ACT4_INTERLUDE_01@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 295
L47_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "USER_ADMIN_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "그럼 가서 하게나."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "では、戻るがいい。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Then do it."
L47_1.m_Talk_ENG = L48_1
L48_1 = "那就去吧。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "งั้นก็ทำซะสิ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Vậy làm đi."
L47_1.m_Talk_VTN = L48_1
L48_1 = "那就去说吧。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Dann tu es."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Alors lève-toi, et vas-y."
L47_1.m_Talk_FRA = L48_1
