L2_1 = "EP7_ACT4_INTERLUDE_01@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 295
L1_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "USER_ADMIN_NULL_NULL"
L1_1.m_CharStrID = L2_1
L2_1 = "자네는 용이 되기를 거부했어. 그러니 용혈의 힘은 더 이상 쓸 수 없겠지."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "君は龍になることを拒んだ。だから龍血の力はこれ以上使えない。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "You refused to become the Dragon. So you won't be able to use the power of the Dragon Blood any longer."
L1_1.m_Talk_ENG = L2_1
L2_1 = "你既然拒絕成為龍，就再也無法使用龍血的力量。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "คุณปฏิเสธไม่ยอมกลายเป็นมังกร ก็เลยใช้พลังของเลือดมังกรไม่ได้อีก"
L1_1.m_Talk_THA = L2_1
L2_1 = "Cậu đã từ chối trở thành con rồng. Vì vậy, cậu sẽ không thể sử dụng sức mạnh của máu rồng nữa."
L1_1.m_Talk_VTN = L2_1
L2_1 = "既然你拒绝成为龙。那龙血的力量也不能再继续使用了。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Du hast dich geweigert, der Drache zu werden. Du kannst die Kraft des Drachenbluts also nicht mehr nutzen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Puisque tu as refusé de devenir un Dragon, tu n'es plus en mesure d'utiliser le pouvoir de ce sang qui coulait dans tes veines."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP7_ACT4_INTERLUDE_01@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 295
L2_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "USER_ADMIN_NULL_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "하지만 그 대신 번뇌를 받아들이고 운명의 저주를 극복해냈어."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "しかしその代わりに煩悩を受け入れて、運命の呪いを乗り越えた。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "But instead, you accepted your Kleshas and overcame your cursed fate."
L2_1.m_Talk_ENG = L3_1
L3_1 = "但你選擇接受煩惱，並且克服了命運的詛咒，"
L2_1.m_Talk_TWN = L3_1
L3_1 = "แต่คุณกลับยอมรับกิเลสและเอาชนะชะตาต้องสาปของตัวเองได้"
L2_1.m_Talk_THA = L3_1
L3_1 = "Nhưng thay vào đó, cậu đã chấp nhận Kleshas của mình và vượt qua số phận bị nguyền rủa của mình."
L2_1.m_Talk_VTN = L3_1
L3_1 = "不过你接受了烦恼，战胜了命运的诅咒。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Aber stattdessen hast du deine Kleshas akzeptiert und dein verfluchtes Schicksal überwunden."
L2_1.m_Talk_DEU = L3_1
L3_1 = "À la place, tu as accepté tes Kleshas. En faisant ainsi, tu as réussi à contrer la malédiction."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP7_ACT4_INTERLUDE_01@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 295
L3_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "USER_ADMIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "자네의 선조들이 남긴 생명과 힘은, 이제부터 그건 자네의 것일세."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "君の先祖たちが遺した生命と力は、これからは君のものだ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "The life force and power your ancestors left behind is now yours."
L3_1.m_Talk_ENG = L4_1
L4_1 = "因此祖先留下的生命和力量現在是你的了。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ตอนนี้พลังชีวิตและพลังที่บรรพบุรุษทิ้งไว้เป็นของคุณแล้ว"
L3_1.m_Talk_THA = L4_1
L4_1 = "Sinh lực và sức mạnh mà tổ tiên cậu để lại bây giờ là của cậu."
L3_1.m_Talk_VTN = L4_1
L4_1 = "你的先祖们留下的生命和力量，从现在开始都是你的了。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Die Lebenskraft und Kraft, die deine Vorfahren hinterlassen haben, gehören jetzt dir."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Le pouvoir et la force vitale de tes ancêtres t'appartiennent, désormais."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP7_ACT4_INTERLUDE_01@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 295
L4_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "USER_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "먼 과거로부터 순환의 뱀처럼 자네에게로 이어진 운명의 끈."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "遠い過去から循環の蛇のように君につながる運命の絆。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "That cord of fate that led to you from a past long gone, like the self-swallowing serpent."
L4_1.m_Talk_ENG = L5_1
L5_1 = "命運的繩索一旦找上你，命運的循環，"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ตรวนชะตากรรมที่ล่ามคุณไว้กับอดีตไกลโพ้นเหมือนงูกินหาง"
L4_1.m_Talk_THA = L5_1
L5_1 = "Sợi dây định mệnh từ quá khứ xa xưa đã dẫn đến cậu, giống như con rắn tự nuốt mình."
L4_1.m_Talk_VTN = L5_1
L5_1 = "从遥远的过去像盘蛇一样延续到你这里的命运之绳。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Diese Schicksalsschnur, die aus einer längst vergangenen Vergangenheit zu dir führte, wie die sich selbst verschlingende Schlange,"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Ce fil du destin venu d'un passé lointain pour arriver jusqu'à toi..."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP7_ACT4_INTERLUDE_01@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 295
L5_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "USER_ADMIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "그 끈이 자네의 삶을 다시 한 번 이어 주겠지."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "その絆が君の人生をもう一度つないでくれるだろう。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "That cord will once again reconnect your life."
L5_1.m_Talk_ENG = L6_1
L6_1 = "會持續在你身上發生。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ตอนนี้ตรวนนั่นจะพาคุณไปเชื่อมต่อกับชีวิตอีกครั้ง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Sợi dây đó sẽ một lần nữa kết nối lại cuộc đời của cậu."
L5_1.m_Talk_VTN = L6_1
L6_1 = "那根绳会再次延续你的生命。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "diese Schnur wird dein Leben wieder verbinden."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Tel Ouroboros, c'est ce fil qui va te relier à la vie."
L5_1.m_Talk_FRA = L6_1
