L10_1 = "EP7_ACT4_INTERLUDE_01@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 295
L9_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "USER_ADMIN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "아 참, 가기 전에 인사는 하고 가게나."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "ああ、戻る前に挨拶をしてから行ってくれ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Oh, you should say hello before you go."
L9_1.m_Talk_ENG = L10_1
L10_1 = "對了，在你離開前打聲招呼再走吧！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "อ้อ ก่อนไปก็ควรไปทักทายเสียก่อนนะ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Ồ, cậu nên chào trước khi đi."
L9_1.m_Talk_VTN = L10_1
L10_1 = "啊，对了，走之前先告个别吧。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Oh, du solltest hallo sagen, bevor du gehst."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Oh, et avant de partir... Il y a quelqu'un que tu devrais saluer."
L9_1.m_Talk_FRA = L10_1
