L11_1 = "EP7_ACT4_INTERLUDE_01@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 295
L10_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "USER_ADMIN_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "자네를 아주 오랫동안 기다려 온 분들이니까."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "君のことを長い間待っていた人たちだからな。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "They've been waiting for you for a very long time."
L10_1.m_Talk_ENG = L11_1
L11_1 = "有人等你很久了。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "พวกนั้นรอคุณมานานมากๆ แล้ว"
L10_1.m_Talk_THA = L11_1
L11_1 = "Họ đã chờ đợi cậu trong một thời gian dài đấy."
L10_1.m_Talk_VTN = L11_1
L11_1 = "他们一直在等你。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Sie haben sehr lange auf dich gewartet."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Des personnes qui t'attendent depuis bien longtemps."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP7_ACT4_INTERLUDE_01@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 295
L11_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "네……? 기다리다니, 누가…… 설마?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "はい……？　待っているって、誰が……まさか？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Sorry…? Waiting for me? Who could have… oh, could it be?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "有人……？在等我？誰啊……難道是？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "อะไรนะครับ...? รอผมเหรอ? ใครที่ไหนจะ... โอ จริงเหรอนั่น?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Xin lỗi…? Chờ tôi? Ai có thể có… oh, có thể nào là?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "嗯……？等我，谁……难道是？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Wie bitte ...? Auf mich gewartet? Wer könnte das ... oh, könnte es sein?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Hein ? Qui m'attendent ? Ne me dites pas que..."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
