L16_1 = "EP7_ACT4_INTERLUDE_01@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 295
L15_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L16_1 = "우리 아들, 정말 많이 컸구나."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "私の息子、大きくなったね。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Oh son, you're all grown up now."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我的兒子，你長大了。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "โอ้ ลูกแม่ โตขนาดนี้แล้วเหรอนี่"
L15_1.m_Talk_THA = L16_1
L16_1 = "Ôi con trai, bây giờ con đã lớn rồi."
L15_1.m_Talk_VTN = L16_1
L16_1 = "我的好儿子，你真的长大了。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Oh, mein Sohn, du bist jetzt erwachsen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Mon fils... Qu'est-ce que tu as grandi !"
L15_1.m_Talk_FRA = L16_1
