L20_1 = "EP7_ACT4_INTERLUDE_01@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 295
L19_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L20_1 = "너한테 꼭…… 미안하다는 말을 하고 싶었단다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "あなたには必ず……謝りたかったの。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "We really wanted to tell you… how sorry we are."
L19_1.m_Talk_ENG = L20_1
L20_1 = "媽媽……一直很想跟你說聲對不起，"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เราอยากบอกเหลือเกิน... ว่าเราเสียใจแค่ไหน"
L19_1.m_Talk_THA = L20_1
L20_1 = "Bố mẹ thực sự muốn nói với con… chúng ta rất tiếc."
L19_1.m_Talk_VTN = L20_1
L20_1 = "我很想……跟你说对不起。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wir wollten dir wirklich gerne sagen ... wie leid es uns tut."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Nous tenions à te dire... que nous sommes désolés."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP7_ACT4_INTERLUDE_01@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 295
L20_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L21_1 = "그리고…… 정말 보고 싶었다는 말도……"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "そして……本当に会いたかった……"
L20_1.m_Talk_JPN = L21_1
L21_1 = "And also… that we miss you dearly…"
L20_1.m_Talk_ENG = L21_1
L21_1 = "還有……媽媽好想你……"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แล้วก็... เราคิดถึงลูกเหลือเกินนะ..."
L20_1.m_Talk_THA = L21_1
L21_1 = "Và nữa… chúng ta rất nhớ con…"
L20_1.m_Talk_VTN = L21_1
L21_1 = "还有……我真的好想你……"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Und auch ... dass wir dich sehr vermissen..."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Et aussi, que tu nous manques..."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
