L26_1 = "EP7_ACT4_INTERLUDE_01@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 295
L25_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L26_1 = "자, 여보. 그만 울고 웃으면서 보내 줍시다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "さあ、泣くのはやめて笑顔で送ってあげよう。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Come dear. Let us put our tears aside and send off our son with a smile."
L25_1.m_Talk_ENG = L26_1
L26_1 = "好了老婆，別再哭了，我們笑著送兒子離開吧。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ไม่เอาน่าที่รัก กลั้นน้ำตาไว้แล้วส่งลูกไปด้วยรอยยิ้มเถอะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Đến đây nào. Chúng ta hãy gạt nước mắt sang một bên và mỉm cười tiễn đưa con trai mình."
L25_1.m_Talk_VTN = L26_1
L26_1 = "好了，亲爱的。别哭了，笑着送孩子离开吧。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Komm, Schatz. Lasst uns unsere Tränen beiseitelegen und unseren Sohn mit einem Lächeln verabschieden."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Allons, chérie. Séchons nos larmes et quittons notre fils dans un sourire."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP7_ACT4_INTERLUDE_01@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 295
L26_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L27_1 = "아들아, 아무리 그립다고 해도 다 큰 자식이 부모 품에 안겨 있을 필요는 없는 법이다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "シリュウ、お前はもう立派な一人前の男だ。\nだから私たちの元を離れても逞しく生きていけると信じている。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "My son, I know you missed us, but a full grown man must leave the embrace of his parents one day."
L26_1.m_Talk_ENG = L27_1
L27_1 = "兒子，雖然爸爸媽媽很想你，但你已經是大人了，必須離開父母的懷抱了。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ลูกพ่อ พ่อรู้ว่าลูกคิดถึงเรา แต่พอเป็นผู้ใหญ่แล้ววันหนึ่งคนเราก็ต้องไปจากอ้อมอกของพ่อแม่นะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Con trai của mẹ, mẹ biết con đã nhớ chúng ta, nhưng một ngày nào đó một người đàn ông trưởng thành phải rời xa vòng tay của cha mẹ."
L26_1.m_Talk_VTN = L27_1
L27_1 = "儿子，不管有多思念，长大的孩子没必要留在父母的怀抱里。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Mein Sohn, ich weiß, dass du uns vermisst hast, aber ein erwachsener Mann muss eines Tages die Umarmung seiner Eltern verlassen."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Je sais que nous devons te manquer, fils. Mais tu es un grand garçon maintenant, tu dois voler de tes propres ailes."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP7_ACT4_INTERLUDE_01@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 295
L27_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L28_1 = "그러니 여기엔…… 가급적이면 천천히 오거라."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "だからここには……できるだけ遅く、ゆっくり来なさい。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "So if at all possible… take your time coming back here."
L27_1.m_Talk_ENG = L28_1
L28_1 = "所以……你在另一個世界要好好活著，不要太快就來這裡找爸爸媽媽。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "แต่ถ้าเป็นไปได้... มีเวลาก็แวะมาบ้างแล้วกัน"
L27_1.m_Talk_THA = L28_1
L28_1 = "Vì vậy, nếu có thể ... hãy dành thời gian quay lại đây."
L27_1.m_Talk_VTN = L28_1
L28_1 = "所以尽量……晚一些再来这里吧。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Also, wenn irgend möglich ... nimm dir viel Zeit, bis du wieder hierher zurückkommst."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Et si possible... Ne nous rejoins pas trop vite, ici."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP7_ACT4_INTERLUDE_01@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 295
L28_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L29_1 = "그리고 스승님께도 전해 주렴."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "そして師匠にも伝えてくれ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "And also please tell the Master…"
L28_1.m_Talk_ENG = L29_1
L29_1 = "幫我帶話給師父，"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แล้วก็ช่วยบอกอาจารย์ด้วยว่า..."
L28_1.m_Talk_THA = L29_1
L29_1 = "Và hãy nói với sư phụ..."
L28_1.m_Talk_VTN = L29_1
L29_1 = "还有，转告你的老师。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Und bitte sag es auch der Meisterin ..."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Oh, et dis au Maître..."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP7_ACT4_INTERLUDE_01@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 295
L29_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "DAD_NPC_YOON_NULL"
L30_1 = "나와 연화, 둘 다 널 이렇게 잘 돌봐 줘서 감사하고 있다고."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "私とレンカ、二人ともお前のことを見守ってくれたことに感謝していると。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "How grateful Yeonhwa and I are for taking such great care of you."
L29_1.m_Talk_ENG = L30_1
L30_1 = "就說，我和蓮華很感謝她這麼照顧你。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ยอนฮวากับพ่อซาบซึ้งใจเหลือเกินที่ช่วยดูแลลูกอย่างยอดเยี่ยมขนาดนี้"
L29_1.m_Talk_THA = L30_1
L30_1 = "Bố và Yeonhwa biết ơn đến nhường nào vì cô ấy đã chăm sóc con."
L29_1.m_Talk_VTN = L30_1
L30_1 = "我跟莲华两个人都很感谢她把你照顾得这么好。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Wie dankbar Yeonhwa und ich sind, dass sie sich so gut um dich gekümmert hat."
L29_1.m_Talk_DEU = L30_1
L30_1 = "... Dis lui notre reconnaissance pour s'être occupée de toi tout ce temps."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
