L34_1 = "……네. 꼭 전할게요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "……はい、必ず伝えます。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "…Yes. I'll be sure to tell her."
L33_1.m_Talk_ENG = L34_1
L34_1 = "……好，我會轉告師父的。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "... ครับ ผมจะบอกเธอให้"
L33_1.m_Talk_THA = L34_1
L34_1 = "…Vâng. Con chắc chắn sẽ nói với cô ấy."
L33_1.m_Talk_VTN = L34_1
L34_1 = "……嗯，我会转告她的。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ja. Ich werde es ihr unbedingt sagen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "D'accord, je lui dirai."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP7_ACT4_INTERLUDE_01@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 295
L34_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "그러니 언젠가 제가 다시 올 때까지…… 잘 지내세요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "だからいつか僕が戻ってくる時まで……お元気で。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "And I wish you the best… until I come back here someday."
L34_1.m_Talk_ENG = L35_1
L35_1 = "等我有一天在來到這裡之前……你們要好好保重。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "โชคดีนะครับ... จนกว่าจะถึงวันที่ผมกลับมาที่นี่อีก"
L34_1.m_Talk_THA = L35_1
L35_1 = "Và con cầu chúc cho bố mẹ những điều tốt đẹp nhất ... cho đến khi con quay lại đây vào một ngày nào đó."
L34_1.m_Talk_VTN = L35_1
L35_1 = "所以直到我们再相逢的那一天……你们要好好的。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Und ich wünsche euch das Beste ... bis ich eines Tages hierher zurückkomme."
L34_1.m_Talk_DEU = L35_1
L35_1 = "D'ici à notre prochaine rencontre... restez en paix."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
