L37_1 = "EP7_ACT4_INTERLUDE_01@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 295
L36_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L37_1 = "몸조심하렴. 밥 꼭 챙겨먹고."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "体に気をつけて、ご飯はちゃんと食べるのよ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Stay safe. And get three square meals a day."
L36_1.m_Talk_ENG = L37_1
L37_1 = "你要好好照顧身體，記得吃飯喔。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ดูแลตัวเองนะลูก กินข้าวให้ครบสามมื้อทุกวันล่ะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Bảo trọng nhé. Và nhớ ăn ba bữa mỗi ngày."
L36_1.m_Talk_VTN = L37_1
L37_1 = "注意身体，好好吃饭。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Pass auf dich auf. Und iss drei ordentliche Mahlzeiten am Tag."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Fais attention à toi, Charles. Et ne mange pas n'importe quoi."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP7_ACT4_INTERLUDE_01@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 295
L37_1.m_CutScenStrID = "EP7_ACT4_INTERLUDE_01"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "MOTHER_NPC_YOON_NULL"
L38_1 = "우린 언제나……."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "私たちはいつだって……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "We'll always…"
L37_1.m_Talk_ENG = L38_1
L38_1 = "爸爸媽媽……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เรา..."
L37_1.m_Talk_THA = L38_1
L38_1 = "Chúng ta sẽ luôn…"
L37_1.m_Talk_VTN = L38_1
L38_1 = "我们永远……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wir werden immer ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Nous serons toujours..."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP7_ACT4_INTERLUDE_01@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 295
